'use strict';

const KEY='schleiferlturnier-v2:main';
const LEGACY_KEYS=[
  'schleiferlturnier-v1:'+location.pathname,
  'schleiferlturnier-v1:'+location.pathname.replace(/index\.html$/i,'Schleiferlturnier_Fotohintergrund.html')
];
const MODE_LABELS={classic:'Schleiferlturnier (wechselnde Doppel)',mixedfixed:'Geloste Doppel aus zwei Kategorien',fixedgroups:'Feste Doppel mit Gruppen',roundrobin:'Round Robin (Feste Doppel ohne Gruppen)',singlesgroups:'Einzel mit Gruppen',singles:'Einzel ohne Gruppen',fixed:'Feste Doppel · Bestand'};
const MODE_OPTIONS=['classic','mixedfixed','fixedgroups','roundrobin','singlesgroups','singles'];
const fresh=()=>({version:2,title:'',mode:'classic',finalStage:'table',pairing:'digital',digitalDrawn:false,manualTeams:[],manualMatches:[],roundMode:'manual',rounds:5,courts:3,minutes:15,breakMinutes:5,groups:[{id:'A',name:'Gruppe A'},{id:'B',name:'Gruppe B'}],players:[...Array(6)].flatMap((_,i)=>[{id:'A'+(i+1),group:'A',name:''},{id:'B'+(i+1),group:'B',name:''}]),fixedTeams:[],schedule:[],results:{},currentRound:0,timer:{remaining:900,end:null,mode:'Spielzeit'}});
let state=fresh(),view='setup',toastTimer,audioContext,wakeLock;
const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const groupIds=()=>state.groups.map(g=>g.id);
const group=id=>state.groups.find(g=>g.id===id);
const players=groupId=>state.players.filter(p=>!groupId||p.group===groupId);
const player=id=>state.players.find(p=>p.id===id);
const groupName=id=>group(id)?.name||`Gruppe ${id}`;
const usesGroups=mode=>['classic','mixedfixed','fixedgroups','singlesgroups'].includes(mode);
const isSinglesMode=mode=>['singlesgroups','singles'].includes(mode);
const supportsPairing=mode=>['classic','mixedfixed','fixedgroups','roundrobin'].includes(mode);
const displayName=id=>player(id)?.name.trim()||`Person ${id}`;
const playerColor=id=>{const i=Math.max(0,state.players.findIndex(p=>p.id===id));return `hsl(${Math.round(i*137.508)%360} 62% 42%)`};
const pairKey=(a,b)=>[a,b].sort().join('|');
const teamKey=ids=>[...ids].sort().join('|');
const timerSeconds=mode=>(mode==='Pause'?state.breakMinutes:state.minutes)*60;
const remaining=()=>state.timer.end?Math.max(0,Math.ceil((state.timer.end-Date.now())/1000)):state.timer.remaining;
const clock=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;

function toast(text){$('#toast').textContent=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',3800)}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#save-status').textContent='Gespeichert'}catch{$('#save-status').textContent='Sicherung empfohlen'}}
function invalidate(resetPairing=false){state.schedule=[];state.results={};state.fixedTeams=[];state.digitalDrawn=false;if(resetPairing){state.manualTeams=[];state.manualMatches=[]}state.currentRound=0;state.timer={remaining:state.minutes*60,end:null,mode:'Spielzeit'};const preview=$('#digital-draw-preview');if(preview)preview.innerHTML='<p class="small muted">Die Eingaben wurden geändert. Bitte erneut auslosen.</p>';releaseWake()}
function locked(){return Object.keys(state.results).length>0}
function hashSeed(text){let h=2166136261;for(const c of text){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
function rngFrom(seed){let x=seed||1;return()=>{x^=x<<13;x^=x>>>17;x^=x<<5;return(x>>>0)/4294967296}}
function shuffled(items,rng=Math.random){const out=[...items];for(let i=out.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out}
function seedRng(extra=''){return rngFrom(hashSeed(state.players.map(p=>`${p.id}:${p.name}`).join(',')+JSON.stringify(state.groups)+state.mode+state.roundMode+state.rounds+state.courts+extra))}

function requestWake(){try{if('wakeLock'in navigator&&document.visibilityState==='visible')navigator.wakeLock.request('screen').then(x=>wakeLock=x).catch(()=>{})}catch{}}
function releaseWake(){try{wakeLock?.release()}catch{}wakeLock=null}
function beep(){try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();const o=audioContext.createOscillator(),g=audioContext.createGain();o.frequency.value=880;g.gain.setValueAtTime(.18,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.8);o.connect(g).connect(audioContext.destination);o.start();o.stop(audioContext.currentTime+.8)}catch{}}
function resetTimer(mode='Spielzeit'){state.timer={remaining:timerSeconds(mode),end:null,mode};releaseWake();persist();updateTimer()}
function updateTimer(){if(state.timer.end&&remaining()===0){state.timer.end=null;state.timer.remaining=0;persist();releaseWake();beep();toast(state.timer.mode==='Spielzeit'?'Zeit um! Nur vollständig beendete Spiele zählen.':'Pause beendet. Nächste Runde kann starten.')}const digits=$('#timer-digits');if(!digits)return;const n=remaining();digits.textContent=`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;$('#timer-mode').textContent=state.timer.mode;$('#timer-status').textContent=state.timer.end?'Läuft':n===0?'Zeit um':'Bereit';$('#timer-toggle').textContent=state.timer.end?'Pause':n===0?'Neu starten':n===timerSeconds(state.timer.mode)?'Start':'Weiter'}
function toggleTimer(){if(state.timer.end){state.timer.remaining=remaining();state.timer.end=null;releaseWake()}else{if(!state.timer.remaining)state.timer.remaining=timerSeconds(state.timer.mode);state.timer.end=Date.now()+state.timer.remaining*1000;requestWake()}persist();updateTimer()}

function maxClassicCourts(){const counts=groupIds().map(id=>players(id).length),total=counts.reduce((a,b)=>a+b,0),max=Math.max(0,...counts),possibleTeams=Math.min(Math.floor(total/2),total-max);return Math.min(state.courts,Math.floor(possibleTeams/2))}
function classicAutoRounds(){const courts=maxClassicCourts();if(courts<1)return 0;const counts=groupIds().map(id=>players(id).length),total=counts.reduce((a,b)=>a+b,0),possibilities=(total*total-counts.reduce((sum,n)=>sum+n*n,0))/2,maxPartners=Math.max(0,...counts.map(n=>total-n));return Math.max(maxPartners,Math.ceil(possibilities/(courts*2)))}
function classicRoundCount(){return state.roundMode==='auto'?classicAutoRounds():state.rounds}
function scheduleStats(){const games=state.schedule.reduce((n,r)=>n+r.matches.length,0),active=state.schedule.length?Math.max(0,...state.schedule.map(r=>r.matches.length)):state.mode==='classic'?maxClassicCourts():isSinglesMode(state.mode)?Math.min(state.courts,Math.floor(state.players.length/2)):Math.min(state.courts,Math.floor(state.players.length/4)),rounds=state.schedule.length||effectiveRoundEstimate(),playDuration=rounds*state.minutes,breakDuration=Math.max(0,rounds-1)*state.breakMinutes;return{games,active,playDuration,breakDuration,duration:playDuration+breakDuration}}
function roundRobinEstimate(entries){const logical=entries%2?entries:Math.max(1,entries-1),matches=Math.floor(entries/2);return logical*Math.max(1,Math.ceil(matches/Math.max(1,state.courts)))}
function groupedRoundRobinEstimate(counts){const logical=counts.map(n=>n%2?n:Math.max(1,n-1)),max=Math.max(0,...logical);let physical=0;for(let r=0;r<max;r++){const matches=counts.reduce((sum,n,i)=>sum+(r<logical[i]?Math.floor(n/2):0),0);physical+=Math.ceil(matches/Math.max(1,state.courts))}return physical}
function effectiveRoundEstimate(){let main=state.mode==='classic'?classicRoundCount():state.rounds;if(state.mode==='singles')main=roundRobinEstimate(state.players.length);if(['roundrobin','mixedfixed'].includes(state.mode))main=roundRobinEstimate(Math.floor(state.players.length/2));if(state.mode==='singlesgroups')main=groupedRoundRobinEstimate(groupIds().map(id=>players(id).length));if(state.mode==='fixedgroups')main=groupedRoundRobinEstimate(groupIds().map(id=>Math.floor(players(id).length/2)));if(state.finalStage!=='placement')return main;return main+(['roundrobin','mixedfixed'].includes(state.mode)?Math.ceil(Math.floor(state.players.length/4)/Math.max(1,state.courts)):2*Math.ceil(2/Math.max(1,state.courts)))}

function chooseClassicPlayers(count,appear,rng){const cap=count/2,chosen=[],groupCount={};for(const p of shuffled(state.players,rng).sort((a,b)=>appear[a.id]-appear[b.id]||rng()-.5)){if(chosen.length===count)break;if((groupCount[p.group]||0)>=cap)continue;chosen.push(p.id);groupCount[p.group]=(groupCount[p.group]||0)+1}return chosen}
function formCrossGroupTeams(ids,partners,rng){const pool=shuffled(ids,rng),teams=[];while(pool.length){pool.sort((a,b)=>{const ac=pool.filter(x=>player(x).group!==player(a).group).length,bc=pool.filter(x=>player(x).group!==player(b).group).length;return ac-bc||rng()-.5});const a=pool.shift(),candidates=pool.filter(x=>player(x).group!==player(a).group);if(!candidates.length)return null;candidates.sort((x,y)=>(partners[pairKey(a,x)]||0)-(partners[pairKey(a,y)]||0)||rng()-.5);const b=candidates[0];pool.splice(pool.indexOf(b),1);teams.push([a,b])}return teams}
function matchPenalty(a,b,opponents){return a.flatMap(x=>b.map(y=>opponents[pairKey(x,y)]||0)).reduce((s,v)=>s+v,0)}
function manualClassicDefinitions(){const courts=maxClassicCourts();return Array.from({length:classicRoundCount()*courts},(_,i)=>({key:`R${Math.floor(i/courts)+1}F${i%courts+1}`,round:Math.floor(i/courts)+1,court:i%courts+1}))}
function syncManualMatches(){const existing=new Map((state.manualMatches||[]).map(m=>[m.key,m.players]));state.manualMatches=manualClassicDefinitions().map(d=>({key:d.key,players:existing.get(d.key)||['','','','']}))}
function generateClassicManual(){const courtCount=maxClassicCourts();if(courtCount<1)throw new Error('Für ein Doppel werden vier Personen aus mindestens zwei Gruppen benötigt.');syncManualMatches();const defs=manualClassicDefinitions(),known=new Set(state.players.map(p=>p.id)),schedule=[],roundCount=classicRoundCount();for(let round=1;round<=roundCount;round++){const entries=defs.map((d,i)=>({d,players:state.manualMatches[i].players})).filter(x=>x.d.round===round),used=[];for(const entry of entries){if(entry.players.some(id=>!known.has(id)))throw new Error(`Bitte Runde ${round} vollständig eintragen.`);if(new Set(entry.players).size!==4)throw new Error(`In Runde ${round} darf jede Person nur einmal pro Begegnung vorkommen.`);if(player(entry.players[0]).group===player(entry.players[1]).group||player(entry.players[2]).group===player(entry.players[3]).group)throw new Error(`In Runde ${round} muss jedes Doppel aus verschiedenen Gruppen bestehen.`);used.push(...entry.players)}if(new Set(used).size!==used.length)throw new Error(`In Runde ${round} darf jede Person nur einmal eingesetzt werden.`);schedule.push({round,type:'regular',matches:entries.map(x=>({id:x.d.key,court:x.d.court,teams:[x.players.slice(0,2),x.players.slice(2,4)]})),byes:state.players.map(p=>p.id).filter(id=>!used.includes(id))})}return schedule}
function generateClassic(){const courtCount=maxClassicCourts();if(courtCount<1)throw new Error('Für ein Doppel werden vier Personen aus mindestens zwei Gruppen benötigt.');const slots=courtCount*4,appear=Object.fromEntries(state.players.map(p=>[p.id,0])),partners={},opponents={},schedule=[],rng=seedRng('classic'),roundCount=classicRoundCount();for(let round=0;round<roundCount;round++){let best=null;for(let attempt=0;attempt<600;attempt++){const selected=chooseClassicPlayers(slots,appear,rng),teams=formCrossGroupTeams(selected,partners,rng);if(!teams)continue;const pool=shuffled(teams,rng),matches=[];while(pool.length){const a=pool.shift();pool.sort((x,y)=>matchPenalty(a,x,opponents)-matchPenalty(a,y,opponents)||rng()-.5);matches.push([a,pool.shift()])}const projected={...appear};selected.forEach(id=>projected[id]++);const values=Object.values(projected),spread=Math.max(...values)-Math.min(...values),partnerRepeats=teams.reduce((n,t)=>n+(partners[pairKey(...t)]||0),0),opponentRepeats=matches.reduce((n,[x,y])=>n+matchPenalty(x,y,opponents),0),score=spread*10000+partnerRepeats*300+opponentRepeats*12+rng();if(!best||score<best.score)best={score,matches,used:new Set(selected)}}if(!best)throw new Error('Mit dieser Gruppenverteilung lässt sich kein gültiger Spielplan bilden.');const roundMatches=best.matches.map((teams,i)=>({id:`R${round+1}F${i+1}`,court:i+1,teams}));schedule.push({round:round+1,type:'regular',matches:roundMatches,byes:state.players.map(p=>p.id).filter(id=>!best.used.has(id))});best.used.forEach(id=>appear[id]++);for(const m of roundMatches){m.teams.forEach(t=>partners[pairKey(...t)]=(partners[pairKey(...t)]||0)+1);for(const a of m.teams[0])for(const b of m.teams[1])opponents[pairKey(a,b)]=(opponents[pairKey(a,b)]||0)+1}}return schedule}

function manualTeamDefinitions(){if(state.mode==='mixedfixed'){const a=players('A').map(p=>p.id),b=players('B').map(p=>p.id),count=Math.min(a.length,b.length);return Array.from({length:count},(_,i)=>({key:`M-${i+1}`,label:`Gemischtes Doppel ${i+1}`,sideLabels:[groupName('A'),groupName('B')],pools:[a,b]}))}if(state.mode==='fixedgroups')return state.groups.flatMap(g=>Array.from({length:Math.floor(players(g.id).length/2)},(_,i)=>({key:`${g.id}-${i+1}`,label:`${g.name} · Doppel ${i+1}`,sideLabels:['Person 1','Person 2'],pools:[players(g.id).map(p=>p.id),players(g.id).map(p=>p.id)]})));const all=state.players.map(p=>p.id);return Array.from({length:Math.floor(all.length/2)},(_,i)=>({key:`T-${i+1}`,label:`Doppel ${i+1}`,sideLabels:['Person 1','Person 2'],pools:[all,all]}))}
function syncManualTeams(){const existing=new Map((state.manualTeams||[]).map(t=>[t.key,t.members]));state.manualTeams=manualTeamDefinitions().map(d=>({key:d.key,members:existing.get(d.key)||['','']}))}
function buildManualTeams(){syncManualTeams();if(state.mode==='fixedgroups')for(const id of groupIds())if(players(id).length<4||players(id).length%2)throw new Error(`${groupName(id)} benötigt für feste Doppel eine gerade Anzahl von mindestens vier Personen.`);const defs=manualTeamDefinitions(),all=state.manualTeams.flatMap(t=>t.members);if(defs.length*2!==state.players.length)throw new Error(state.mode==='mixedfixed'?'Gruppe A und Gruppe B müssen gleich groß sein.':'Für feste Doppel wird eine gerade Anzahl an Personen benötigt.');if(all.some(id=>!id))throw new Error('Bitte alle manuellen Doppel vollständig eintragen.');if(new Set(all).size!==all.length)throw new Error('Jede Person darf nur einem Doppel zugeordnet sein.');for(let i=0;i<defs.length;i++)for(let side=0;side<2;side++)if(!defs[i].pools[side].includes(state.manualTeams[i].members[side]))throw new Error('Eine manuelle Paarung passt nicht zu den Vorgaben des Modus.');return state.manualTeams.map(t=>[...t.members])}
function buildFixedTeams(){if(state.players.length<4||state.players.length%2)throw new Error('Für feste Doppel wird eine gerade Anzahl von mindestens vier Personen benötigt.');const pool=state.pairing==='manual'?state.players.map(p=>p.id):shuffled(state.players.map(p=>p.id),seedRng('teams'));return Array.from({length:pool.length/2},(_,i)=>pool.slice(i*2,i*2+2))}
function buildFixedTeamsByGroup(){const teams=[];for(const id of groupIds()){const list=players(id);if(list.length<4||list.length%2)throw new Error(`${groupName(id)} benötigt für feste Doppel eine gerade Anzahl von mindestens vier Personen.`);const pool=state.pairing==='manual'?list.map(p=>p.id):shuffled(list.map(p=>p.id),seedRng(`teams-${id}`));for(let i=0;i<pool.length;i+=2)teams.push(pool.slice(i,i+2))}return teams}
function buildMixedTeams(){if(state.groups.length!==2||!group('A')||!group('B'))throw new Error('Dieser Modus benötigt genau Gruppe A und Gruppe B.');const a=players('A'),b=players('B');if(a.length<2||a.length!==b.length)throw new Error('Gruppe A und Gruppe B müssen gleich groß sein und jeweils mindestens zwei Personen enthalten.');if(state.pairing==='manual')return a.map((p,i)=>[p.id,b[i].id]);const rng=seedRng('mixed-teams'),left=shuffled(a.map(p=>p.id),rng),right=shuffled(b.map(p=>p.id),rng);return left.map((id,i)=>[id,right[i]])}
function circleRounds(teams){const list=teams.map(t=>[...t]);if(list.length%2)list.push(null);const rounds=[];for(let r=0;r<list.length-1;r++){const pairs=[];for(let i=0;i<list.length/2;i++){const a=list[i],b=list[list.length-1-i];if(a&&b)pairs.push([a,b])}rounds.push(pairs);list.splice(1,0,list.pop())}return rounds}
function addPhysicalRounds(target,pairRounds,desired,rng){let index=0,cycle=0;while(target.length<desired){if(!pairRounds.length)break;const pairRound=pairRounds[index%pairRounds.length],chunks=[];for(let i=0;i<pairRound.length;i+=state.courts)chunks.push(pairRound.slice(i,i+state.courts));for(const chunk of chunks){if(target.length>=desired)break;const used=new Set(chunk.flat(2)),number=target.length+1;target.push({round:number,type:'regular',matches:chunk.map((teams,i)=>({id:`R${number}F${i+1}`,court:i+1,teams})),byes:state.players.map(p=>p.id).filter(id=>!used.has(id))})}index++;if(index%pairRounds.length===0){cycle++;if(cycle>20)break;pairRounds=circleRounds(shuffled(state.fixedTeams,rng))}}}
function appendPlacementRounds(schedule){const pairs=[];for(let rank=1;rank<=state.fixedTeams.length;rank+=2)if(rank+1<=state.fixedTeams.length)pairs.push([rank,rank+1]);for(let i=0;i<pairs.length;i+=state.courts){const number=schedule.length+1,chunk=pairs.slice(i,i+state.courts);schedule.push({round:number,type:'placement',matches:chunk.map((placement,j)=>({id:`P${placement[0]}-${placement[1]}`,court:j+1,placement,teams:null})),byes:[]})}}
function generateFixed(roundRobin=false){state.fixedTeams=buildFixedTeams();const rng=seedRng(roundRobin?'rr':'fixed'),pairRounds=circleRounds(state.fixedTeams),schedule=[];const physicalPerCycle=pairRounds.reduce((n,r)=>n+Math.max(1,Math.ceil(r.length/state.courts)),0),desired=roundRobin?physicalPerCycle:state.rounds;addPhysicalRounds(schedule,pairRounds,desired,rng);if(state.finalStage==='placement')appendPlacementRounds(schedule);return schedule}
function generateMixedFixed(){state.fixedTeams=buildMixedTeams();const schedule=[],rng=seedRng('mixed-roundrobin'),pairRounds=circleRounds(state.fixedTeams),desired=pairRounds.reduce((n,r)=>n+Math.max(1,Math.ceil(r.length/state.courts)),0);addPhysicalRounds(schedule,pairRounds,desired,rng);if(state.finalStage==='placement')appendPlacementRounds(schedule);return schedule}
function addGroupedRounds(schedule,logical,type='group'){const count=Math.max(0,...logical.map(x=>x.rounds.length));for(let r=0;r<count;r++){const pairs=logical.flatMap(x=>(x.rounds[r]||[]).map((teams,pairIndex)=>({group:x.id,pairIndex,teams})));for(let start=0;start<pairs.length;start+=state.courts){const chunk=pairs.slice(start,start+state.courts),number=schedule.length+1,active=new Set(chunk.flatMap(x=>x.teams.flat()));schedule.push({round:number,type,matches:chunk.map((x,i)=>({id:`G${x.group}R${r+1}M${x.pairIndex+1}`,court:i+1,group:x.group,teams:x.teams})),byes:state.players.map(p=>p.id).filter(id=>!active.has(id))})}}}
function appendFinals(schedule,entryCount){if(entryCount<4)throw new Error('Für Halbfinale und Finale werden mindestens vier Personen beziehungsweise Doppel benötigt.');const semis=[{id:'SF1',seed:[1,4]},{id:'SF2',seed:[2,3]}];for(let i=0;i<semis.length;i+=state.courts){const number=schedule.length+1;schedule.push({round:number,type:'semifinal',matches:semis.slice(i,i+state.courts).map((m,j)=>({...m,court:j+1,teams:null})),byes:[]})}const finals=[{id:'F1',label:'Finale',sources:[{matchId:'SF1',outcome:'winner'},{matchId:'SF2',outcome:'winner'}]},{id:'F3',label:'Spiel um Platz 3',sources:[{matchId:'SF1',outcome:'loser'},{matchId:'SF2',outcome:'loser'}]}];for(let i=0;i<finals.length;i+=state.courts){const number=schedule.length+1;schedule.push({round:number,type:'final',matches:finals.slice(i,i+state.courts).map((m,j)=>({...m,court:j+1,teams:null})),byes:[]})}}
function generateSingles(grouped=false){if(state.players.length<2)throw new Error('Für Einzelspiele werden mindestens zwei Personen benötigt.');const schedule=[];if(grouped){if(state.groups.some(g=>players(g.id).length<2))throw new Error('Jede Gruppe benötigt mindestens zwei Personen.');addGroupedRounds(schedule,state.groups.map(g=>({id:g.id,rounds:circleRounds(players(g.id).map(p=>[p.id]))})))}else{const pairRounds=circleRounds(state.players.map(p=>[p.id]));for(const logical of pairRounds)for(let start=0;start<logical.length;start+=state.courts){const chunk=logical.slice(start,start+state.courts),number=schedule.length+1,active=new Set(chunk.flat(2));schedule.push({round:number,type:'regular',matches:chunk.map((teams,i)=>({id:`R${number}F${i+1}`,court:i+1,teams})),byes:state.players.map(p=>p.id).filter(id=>!active.has(id))})}}if(state.finalStage==='placement')appendFinals(schedule,state.players.length);return schedule}
function generateFixedGroups(){state.fixedTeams=buildFixedTeamsByGroup();const schedule=[],logical=state.groups.map(g=>({id:g.id,rounds:circleRounds(state.fixedTeams.filter(t=>player(t[0]).group===g.id))}));addGroupedRounds(schedule,logical);if(state.finalStage==='placement')appendFinals(schedule,state.fixedTeams.length);return schedule}
function generate(){if(locked()){toast('Nach dem ersten Ergebnis kann der Spielplan erst in einem neuen Turnier geändert werden.');return}try{state.title=state.title.trim()||'Turnier';state.fixedTeams=[];state.schedule=state.mode==='classic'?generateClassic():state.mode==='mixedfixed'?generateMixedFixed():state.mode==='fixedgroups'?generateFixedGroups():state.mode==='roundrobin'?generateFixed(true):state.mode==='singlesgroups'?generateSingles(true):state.mode==='singles'?generateSingles(false):generateFixed(false);state.results={};state.currentRound=0;state.timer={remaining:state.minutes*60,end:null,mode:'Spielzeit'};releaseWake();persist();view='schedule';render();toast(`${MODE_LABELS[state.mode]}: Spielplan mit ${state.schedule.length} Runden erstellt.`)}catch(e){toast(e.message)}}

function addPlayer(groupId=state.groups[0].id){if(locked()){toast('Nach dem ersten Ergebnis können Personen erst in einem neuen Turnier geändert werden.');return}const used=new Set(state.players.map(p=>p.id));let n=1,id;do{id=groupId+n++}while(used.has(id));state.players.push({id,group:groupId,name:''});invalidate(true);persist();render();requestAnimationFrame(()=>document.querySelector(`[data-player="${id}"]`)?.focus())}
function removePlayer(id){if(locked()){toast('Nach dem ersten Ergebnis können Personen erst in einem neuen Turnier geändert werden.');return}const p=player(id);if(usesGroups(state.mode)&&players(p.group).length<=2){toast('Pro Gruppe müssen mindestens zwei Personen bleiben.');return}if(!usesGroups(state.mode)&&state.players.length<=2){toast('Mindestens zwei Personen müssen bestehen bleiben.');return}state.players=state.players.filter(x=>x.id!==id);invalidate(true);persist();render()}
function nextGroupId(){return 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('').find(id=>!groupIds().includes(id))}
function addGroup(){if(locked()){toast('Nach dem ersten Ergebnis können Gruppen erst in einem neuen Turnier geändert werden.');return}if(state.mode==='mixedfixed'){toast('Im Modus Gruppe A + Gruppe B können keine weiteren Gruppen angelegt werden.');return}const id=nextGroupId();if(!id){toast('Es können keine weiteren Gruppen angelegt werden.');return}state.groups.push({id,name:`Gruppe ${id}`});for(let i=1;i<=4;i++)state.players.push({id:id+i,group:id,name:''});invalidate(true);persist();render();toast(`Gruppe ${id} wurde hinzugefügt.`)}
function removeGroup(id){if(locked()){toast('Nach dem ersten Ergebnis können Gruppen erst in einem neuen Turnier geändert werden.');return}if(state.mode==='mixedfixed'){toast('Dieser Modus benötigt genau Gruppe A und Gruppe B.');return}if(state.groups.length<=1){toast('Mindestens eine Gruppe muss bestehen bleiben.');return}if(!confirm(`${groupName(id)} und alle darin eingetragenen Personen entfernen?`))return;state.groups=state.groups.filter(g=>g.id!==id);state.players=state.players.filter(p=>p.group!==id);invalidate(true);persist();render();toast(`Gruppe ${id} wurde entfernt.`)}
function drawPlayers(){if(locked()){toast('Nach dem ersten Ergebnis ist eine neue Auslosung erst in einem neuen Turnier möglich.');return}if(state.players.some(p=>!p.name.trim())){toast('Bitte zuerst bei allen Personen einen Namen eintragen.');return}const scope=usesGroups(state.mode)?'innerhalb ihrer Gruppen':'in der Teilnehmerliste';if(state.schedule.length&&!confirm(`Die Namen werden ${scope} neu ausgelost und der Spielplan wird ersetzt. Fortfahren?`))return;if(usesGroups(state.mode)){for(const id of groupIds()){const names=shuffled(players(id).map(p=>p.name));players(id).forEach((p,i)=>p.name=names[i])}}else{const names=shuffled(state.players.map(p=>p.name));state.players.forEach((p,i)=>p.name=names[i])}invalidate(true);state.digitalDrawn=true;persist();render();toast('Auslosung abgeschlossen. Die gelosten Doppel werden jetzt angezeigt.')}

function resolvedTeams(match){if(match.teams)return match.teams;if(match.placement){const regularIndexes=state.schedule.map((r,i)=>r.type!=='placement'?i:-1).filter(i=>i>=0);if(!regularIndexes.every(roundComplete))return[[],[]];const base=fixedStandings(false).rows;return match.placement.map(rank=>base[rank-1]?.members||[])}if(match.seed){const mainIndexes=state.schedule.map((r,i)=>!['semifinal','final'].includes(r.type)?i:-1).filter(i=>i>=0);if(!mainIndexes.every(roundComplete))return[[],[]];const base=state.mode==='fixedgroups'?fixedGroupStandings(false):state.mode==='singlesgroups'?singleGroupStandings(false):singleOverallStandings(false);return match.seed.map(rank=>{const row=base.rows[rank-1];return row?(row.members||[row.id]):[]})}if(match.sources){return match.sources.map(source=>{const origin=allMatches().find(m=>m.id===source.matchId),score=state.results[source.matchId],teams=origin?resolvedTeams(origin):[[],[]];if(!score||teams.some(t=>!t.length)||score[0]===score[1])return[];const winner=score[0]>score[1]?0:1,index=source.outcome==='winner'?winner:1-winner;return teams[index]})}return[[],[]]}
function roundByes(round){if(!['placement','semifinal','final'].includes(round.type))return round.byes;const active=new Set(round.matches.flatMap(m=>resolvedTeams(m).flat()));return state.players.map(p=>p.id).filter(id=>!active.has(id))}
function allMatches(){return state.schedule.flatMap(r=>r.matches)}
function roundResultCount(index){const r=state.schedule[index];return r?r.matches.filter(m=>state.results[m.id]).length:0}
function roundComplete(index){const r=state.schedule[index];return !!r&&r.matches.length>0&&roundResultCount(index)===r.matches.length}
function roundUnlocked(index){return index===0||state.schedule.slice(0,index).every((_,i)=>roundComplete(i))}

function individualStandings(){const rows=state.players.map(p=>({kind:'player',id:p.id,name:displayName(p.id),group:p.group,played:0,wins:0,draws:0,points:0,for:0,against:0,diff:0})),map=Object.fromEntries(rows.map(r=>[r.id,r]));for(const r of state.schedule)for(const m of r.matches){const score=state.results[m.id],teams=resolvedTeams(m);if(!score||!teams[0].length)continue;for(let side=0;side<2;side++)for(const id of teams[side]){const row=map[id];row.played++;row.for+=score[side];row.against+=score[1-side];if(score[0]===score[1]){row.draws++;row.points++}else if(score[side]>score[1-side]){row.wins++;row.points+=2}}}rankRows(rows);return{kind:'player',rows}}
function rankRows(rows){rows.forEach(r=>r.diff=r.for-r.against);rows.sort((a,b)=>b.points-a.points||b.diff-a.diff||b.for-a.for||(a.name||a.id).localeCompare(b.name||b.id,'de'));rows.forEach(r=>r.rank=r.played?1+rows.filter(o=>o.played&&(o.points>r.points||(o.points===r.points&&o.diff>r.diff)||(o.points===r.points&&o.diff===r.diff&&o.for>r.for))).length:null)}
function addScore(rowsByKey,teams,score,keyOf){const found=teams.map(t=>rowsByKey[keyOf(t)]);if(found.some(x=>!x))return;for(let side=0;side<2;side++){const row=found[side];row.played++;row.for+=score[side];row.against+=score[1-side];if(score[0]===score[1]){row.draws++;row.points++}else if(score[side]>score[1-side]){row.wins++;row.points+=2}}}
function applyFinalResults(rows){const lookup=Object.fromEntries(rows.map(r=>[r.members?teamKey(r.members):r.id,r]));for(const round of state.schedule.filter(r=>['semifinal','final'].includes(r.type)))for(const m of round.matches){const score=state.results[m.id],teams=resolvedTeams(m);if(!score||teams.some(t=>!t.length))continue;addScore(lookup,teams,score,t=>t.length===1&&!rows[0]?.members?t[0]:teamKey(t));if(m.id==='F1'&&score[0]!==score[1]){lookup[rows[0]?.members?teamKey(teams[score[0]>score[1]?0:1]):teams[score[0]>score[1]?0:1][0]].rank=1;lookup[rows[0]?.members?teamKey(teams[score[0]>score[1]?1:0]):teams[score[0]>score[1]?1:0][0]].rank=2}if(m.id==='F3'&&score[0]!==score[1]){lookup[rows[0]?.members?teamKey(teams[score[0]>score[1]?0:1]):teams[score[0]>score[1]?0:1][0]].rank=3;lookup[rows[0]?.members?teamKey(teams[score[0]>score[1]?1:0]):teams[score[0]>score[1]?1:0][0]].rank=4}}rows.forEach(r=>r.diff=r.for-r.against);rows.sort((a,b)=>(a.rank??999)-(b.rank??999)||b.points-a.points||b.diff-a.diff)}
function fixedStandings(includePlacement=true){const rows=state.fixedTeams.map((members,i)=>({kind:'team',id:`T${i+1}`,name:members.map(displayName).join(' & '),members:[...members],played:0,wins:0,draws:0,points:0,for:0,against:0,diff:0})),map=Object.fromEntries(rows.map(r=>[teamKey(r.members),r]));for(const round of state.schedule.filter(r=>r.type!=='placement'))for(const m of round.matches){const score=state.results[m.id];if(!score)continue;const teams=m.teams,found=teams.map(t=>map[teamKey(t)]);if(found.some(x=>!x))continue;for(let side=0;side<2;side++){const row=found[side];row.played++;row.for+=score[side];row.against+=score[1-side];if(score[0]===score[1]){row.draws++;row.points++}else if(score[side]>score[1-side]){row.wins++;row.points+=2}}}rankRows(rows);if(!includePlacement)return{kind:'team',rows};rows.forEach((r,i)=>r.rank=i+1);const base=[...rows];for(const round of state.schedule.filter(r=>r.type==='placement'))for(const m of round.matches){const score=state.results[m.id],pair=m.placement.map(rank=>base[rank-1]);if(!score||pair.some(x=>!x))continue;for(let side=0;side<2;side++){pair[side].played++;pair[side].for+=score[side];pair[side].against+=score[1-side];if(score[0]===score[1])pair[side].draws++;else if(score[side]>score[1-side])pair[side].wins++}if(score[0]!==score[1]){const winner=score[0]>score[1]?0:1;pair[winner].rank=m.placement[0];pair[1-winner].rank=m.placement[1]}}rows.sort((a,b)=>(a.rank??999)-(b.rank??999));rows.forEach(r=>r.diff=r.for-r.against);return{kind:'team',rows}}
function groupedRows(kind){return state.groups.map(g=>{const entries=kind==='team'?state.fixedTeams.filter(t=>player(t[0]).group===g.id):players(g.id).map(p=>[p.id]);const rows=entries.map((members,i)=>kind==='team'?{kind:'team',id:`${g.id}T${i+1}`,name:members.map(displayName).join(' & '),members:[...members],group:g.id,played:0,wins:0,draws:0,points:0,for:0,against:0,diff:0}:{kind:'player',id:members[0],name:displayName(members[0]),group:g.id,played:0,wins:0,draws:0,points:0,for:0,against:0,diff:0}),map=Object.fromEntries(rows.map(r=>[kind==='team'?teamKey(r.members):r.id,r]));for(const round of state.schedule.filter(r=>r.type==='group'))for(const m of round.matches){const score=state.results[m.id];if(score&&m.group===g.id)addScore(map,m.teams,score,t=>kind==='team'?teamKey(t):t[0])}rankRows(rows);return{id:g.id,name:g.name,rows}})}
function groupedStandings(kind,includeFinals=true){const groups=groupedRows(kind),rows=groups.flatMap(x=>x.rows).sort((a,b)=>(a.rank??999)-(b.rank??999)||b.points-a.points||b.diff-a.diff||b.for-a.for||a.name.localeCompare(b.name,'de')).map((r,i)=>({...r,members:r.members?[...r.members]:undefined,rank:i+1}));if(includeFinals)applyFinalResults(rows);return{kind,rows,groups}}
function singleGroupStandings(includeFinals=true){return groupedStandings('player',includeFinals)}
function fixedGroupStandings(includeFinals=true){return groupedStandings('team',includeFinals)}
function singleOverallStandings(includeFinals=true){const rows=state.players.map(p=>({kind:'player',id:p.id,name:displayName(p.id),group:p.group,played:0,wins:0,draws:0,points:0,for:0,against:0,diff:0})),map=Object.fromEntries(rows.map(r=>[r.id,r]));for(const round of state.schedule.filter(r=>r.type==='regular'))for(const m of round.matches){const score=state.results[m.id];if(score)addScore(map,m.teams,score,t=>t[0])}rankRows(rows);if(includeFinals){rows.forEach((r,i)=>r.rank=i+1);applyFinalResults(rows)}return{kind:'player',rows}}
function standings(){return state.mode==='classic'?individualStandings():state.mode==='singlesgroups'?singleGroupStandings(true):state.mode==='singles'?singleOverallStandings(true):state.mode==='fixedgroups'?fixedGroupStandings(true):fixedStandings(true)}

function renderSetup(){const s=scheduleStats(),possible=state.mode==='classic'?maxClassicCourts():state.mode==='singles'?Math.min(state.courts,Math.floor(state.players.length/2)):Math.min(state.courts,Math.floor(state.players.length/4)),isLocked=locked(),autoRounds=['roundrobin','singles'].includes(state.mode);return `<div class="intro"><div><div class="eyebrow">Turnier vorbereiten</div><h2>Modus, Gruppen und Personen</h2></div><span class="muted">${state.groups.length} Gruppen · ${state.players.length} Personen</span></div>${isLocked?'<div class="notice">Planung gesperrt: Es wurde bereits ein Ergebnis gespeichert. Änderungen sind erst nach „Neues Turnier“ möglich.</div>':''}<div class="draw-toolbar"><button class="primary" id="draw-players" ${isLocked?'disabled':''}>Digital auslosen</button><button class="ghost" id="print-players">Spielerliste drucken</button><button class="ghost" id="print-lots">Loskarten drucken</button></div><div class="setup-grid"><div class="settings"><section class="panel"><h3>Rahmen</h3><div style="margin-top:16px"><label for="title">Turniername</label><input id="title" maxlength="80" value="${esc(state.title)}" ${isLocked?'disabled':''}></div><label style="margin-top:14px">Spielmodus</label><div class="mode-grid">${Object.entries(MODE_LABELS).map(([id,label])=>`<label class="mode-card"><input type="radio" name="mode" value="${id}" ${state.mode===id?'checked':''} ${isLocked?'disabled':''}><strong>${label}</strong><span>${id==='classic'?'Partner wechseln in jeder Runde.':id==='fixed'?'Einmal ausgeloste Doppel bleiben zusammen.':id==='roundrobin'?'Feste Doppel spielen vollständig jeder gegen jeden.':'Einzel-Round-Robin je Gruppe, optional mit Halbfinale und Finale.'}</span></label>`).join('')}</div><div class="settings-grid" style="margin-top:14px"><div><label for="round-count">${autoRounds?'Runden automatisch':'Runden'}</label><input id="round-count" type="number" min="1" max="40" value="${state.rounds}" ${autoRounds||isLocked?'disabled':''}></div><div><label for="court-count">Plätze</label><input id="court-count" type="number" min="1" max="12" value="${state.courts}" ${isLocked?'disabled':''}></div></div><div class="settings-grid" style="margin-top:12px"><div><label for="minutes">Minuten je Runde</label><input id="minutes" type="number" min="5" max="60" value="${state.minutes}"></div><div><label for="break-minutes">Pausenzeit</label><input id="break-minutes" type="number" min="0" max="60" value="${state.breakMinutes}"></div></div><div style="margin-top:14px"><label for="final-stage">Turnierabschluss</label><select id="final-stage" ${state.mode==='classic'||isLocked?'disabled':''}><option value="table" ${state.finalStage==='table'?'selected':''}>${state.mode==='singles'?'Nach Gruppentabellen auswerten':'Nach Tabelle auswerten'}</option><option value="placement" ${state.finalStage==='placement'?'selected':''}>${state.mode==='singles'?'Halbfinale und Finale spielen':'Platzierungsspiele durchführen'}</option></select><div class="mode-note">${state.mode==='classic'?'Beim klassischen Schleiferl entscheidet die Einzelwertung. Finalspiele stehen für feste Doppel, Round Robin und Einzel zur Verfügung.':state.mode==='singles'?(state.finalStage==='placement'?'Die vier bestgesetzten Personen spielen über Kreuz Halbfinale, Finale und Platz 3.':'Jede Gruppe wird nach ihrer eigenen Abschlusstabelle gewertet.'):state.finalStage==='placement'?'Nach der Vorrunde spielen Platz 1 gegen 2, 3 gegen 4 usw.':'Die Tabelle nach der letzten Runde ist das Endergebnis.'}</div></div></section><section class="panel summary"><div class="small muted">Mit der aktuellen Konfiguration</div><div class="summary-grid"><div class="summary-item"><strong>${possible}</strong><span class="small">Plätze gleichzeitig</span></div><div class="summary-item"><strong>${autoRounds?'Auto':state.rounds}</strong><span class="small">${autoRounds?'Runden':'Runden geplant'}</span></div><div class="summary-item"><strong>${s.duration}</strong><span class="small">Minuten circa</span></div></div><button class="gold" id="generate" style="width:100%" ${isLocked?'disabled':''}>Spielplan erstellen</button></section></div><div><div class="group-toolbar"><div><h3>Teilnehmergruppen</h3><p class="small muted" style="margin-top:5px">${state.mode==='singles'?'In der Gruppenphase spielt jede Person gegen alle anderen ihrer Gruppe.':'Doppel werden immer aus Personen verschiedener Gruppen gebildet.'}</p></div><button class="ghost" id="add-group" ${isLocked?'disabled':''}>+ Gruppe hinzufügen</button></div><div class="player-columns">${state.groups.map(g=>`<section class="panel group-panel"><div class="category-head"><div><input class="group-title" data-group-name="${g.id}" maxlength="30" value="${esc(g.name)}" aria-label="Name Gruppe ${g.id}" ${isLocked?'disabled':''}><div class="color-legend">${players(g.id).length} Personen · Kennung ${g.id}</div></div><div class="group-actions"><button class="ghost icon-btn" data-add="${g.id}" aria-label="Person hinzufügen" ${isLocked?'disabled':''}>+</button><button class="danger icon-btn" data-remove-group="${g.id}" aria-label="Gruppe entfernen" ${isLocked||state.groups.length<=2?'disabled':''}>×</button></div></div><div class="player-list">${players(g.id).map((p,i)=>`<div class="player-row"><span class="player-code" style="--player-color:${playerColor(p.id)}">${p.id}</span><input data-player="${p.id}" aria-label="Name ${g.name} ${i+1}" maxlength="60" placeholder="Name" value="${esc(p.name)}" ${isLocked?'disabled':''}><button class="danger icon-btn" data-remove="${p.id}" aria-label="${esc(displayName(p.id))} entfernen" ${isLocked?'disabled':''}>×</button></div>`).join('')}</div></section>`).join('')}</div></div></div><div class="footer-note"><span>Bestehende Sicherungen werden automatisch übernommen.</span><span>${state.mode==='singles'?'Die Gruppenspiele werden automatisch auf die verfügbaren Plätze verteilt.':'Ungleiche Gruppen werden durch faire Pausen ausgeglichen.'}</span></div>`}

function bindSetup(){$$('[data-player]').forEach(i=>i.oninput=()=>{player(i.dataset.player).name=i.value;invalidate();persist()});$$('[data-group-name]').forEach(i=>i.oninput=()=>{group(i.dataset.groupName).name=i.value||`Gruppe ${i.dataset.groupName}`;persist()});$$('[data-add]').forEach(b=>b.onclick=()=>addPlayer(b.dataset.add));$$('[data-remove]').forEach(b=>b.onclick=()=>removePlayer(b.dataset.remove));$$('[data-remove-group]').forEach(b=>b.onclick=()=>removeGroup(b.dataset.removeGroup));$('#add-group').onclick=addGroup;$('#title').oninput=e=>{state.title=e.target.value;persist()};$$('[name=mode]').forEach(i=>i.onchange=()=>{state.mode=i.value;if(state.mode==='classic')state.finalStage='table';invalidate();persist();render()});$('#final-stage').onchange=e=>{state.finalStage=e.target.value;invalidate();persist();render()};$('#round-count').onchange=e=>{state.rounds=Math.max(1,Math.min(40,Number(e.target.value)||1));invalidate();persist();render()};$('#court-count').onchange=e=>{state.courts=Math.max(1,Math.min(12,Number(e.target.value)||1));invalidate();persist();render()};$('#minutes').onchange=e=>{state.minutes=Math.max(5,Math.min(60,Number(e.target.value)||15));resetTimer('Spielzeit');render()};$('#break-minutes').onchange=e=>{state.breakMinutes=Math.max(0,Math.min(60,Number(e.target.value)||0));if(state.timer.mode==='Pause')resetTimer('Pause');else persist();render()};$('#draw-players').onclick=drawPlayers;$('#print-players').onclick=()=>printExtras('players');$('#print-lots').onclick=()=>printExtras('lots');$('#generate').onclick=generate}

const MODE_DESCRIPTIONS={fixedgroups:'Feste Doppel werden innerhalb der Gruppen ausgelost und spielen dort jeder gegen jeden.',roundrobin:'Feste Doppel spielen ohne Gruppen vollständig jeder gegen jeden.',singlesgroups:'Einzelspiele als Jeder-gegen-jeden innerhalb der Gruppen.',singles:'Alle Personen spielen im Einzel ohne Gruppen jeder gegen jeden.'};
function playerInputRow(p,index,lockedState,flat=false){return `<div class="player-row ${flat?'flat-player-row':''}"><span class="player-code" style="--player-color:${playerColor(p.id)}">${flat?index+1:p.id}</span><input data-player="${p.id}" aria-label="Name Person ${index+1}" maxlength="60" placeholder="Name" value="${esc(p.name)}" ${lockedState?'disabled':''}><button class="danger icon-btn" data-remove="${p.id}" aria-label="${esc(displayName(p.id))} entfernen" ${lockedState?'disabled':''}>×</button></div>`}
function renderParticipantSetup(isLocked){if(!usesGroups(state.mode))return `<div><div class="group-toolbar participant-toolbar"><div><h3>Teilnehmerliste</h3><p class="small muted" style="margin-top:5px">In diesem Modus gibt es keine Gruppen. Alle Personen stehen in einer gemeinsamen Liste.</p></div><button class="ghost" id="add-player" ${isLocked?'disabled':''}>+ Person hinzufügen</button></div><section class="panel participant-list-panel"><div class="participant-list">${state.players.map((p,i)=>playerInputRow(p,i,isLocked,true)).join('')}</div></section></div>`;return `<div><div class="group-toolbar"><div><h3>Teilnehmergruppen</h3><p class="small muted" style="margin-top:5px">${state.mode==='fixedgroups'?'Die festen Doppel werden innerhalb ihrer jeweiligen Gruppe ausgelost.':'In der Gruppenphase spielt jede Person gegen alle anderen ihrer Gruppe.'}</p></div><button class="ghost" id="add-group" ${isLocked?'disabled':''}>+ Gruppe hinzufügen</button></div><div class="player-columns">${state.groups.map(g=>`<section class="panel group-panel"><div class="category-head"><div><input class="group-title" data-group-name="${g.id}" maxlength="30" value="${esc(g.name)}" aria-label="Name Gruppe ${g.id}" ${isLocked?'disabled':''}><div class="color-legend">${players(g.id).length} Personen · Kennung ${g.id}</div></div><div class="group-actions"><button class="ghost" data-add="${g.id}" ${isLocked?'disabled':''}>+ Person</button><button class="danger remove-group-button" data-remove-group="${g.id}" ${isLocked||state.groups.length<=1?'disabled':''}>Gruppe entfernen</button></div></div><div class="player-list">${players(g.id).map((p,i)=>playerInputRow(p,i,isLocked)).join('')}</div></section>`).join('')}</div></div>`}
function renderSetupModern(){const s=scheduleStats(),possible=isSinglesMode(state.mode)?Math.min(state.courts,Math.floor(state.players.length/2)):Math.min(state.courts,Math.floor(state.players.length/4)),isLocked=locked(),autoRounds=MODE_OPTIONS.includes(state.mode),grouped=usesGroups(state.mode),finalLabel=grouped?'Nach Gruppentabellen auswerten':'Nach Tabelle auswerten',finalPlay=isSinglesMode(state.mode)||state.mode==='fixedgroups'?'Halbfinale und Finale spielen':'Platzierungsspiele durchführen';return `<div class="intro"><div><div class="eyebrow">Turnier vorbereiten</div><h2>Modus und Teilnehmer</h2></div><span class="muted">${grouped?`${state.groups.length} Gruppen · `:''}${state.players.length} Personen</span></div>${isLocked?'<div class="notice">Planung gesperrt: Es wurde bereits ein Ergebnis gespeichert. Änderungen sind erst nach „Neues Turnier“ möglich.</div>':''}<div class="draw-toolbar"><button class="primary" id="draw-players" ${isLocked?'disabled':''}>Digital auslosen</button><button class="ghost" id="print-players">Spielerliste drucken</button><button class="ghost" id="print-lots">Loskarten drucken</button></div><div class="setup-grid"><div class="settings"><section class="panel"><h3>Rahmen</h3><div style="margin-top:16px"><label for="title">Turniername</label><input id="title" maxlength="80" value="${esc(state.title)}" ${isLocked?'disabled':''}></div><label style="margin-top:14px">Spielmodus</label><div class="mode-grid">${MODE_OPTIONS.map(id=>`<label class="mode-card"><input type="radio" name="mode" value="${id}" ${state.mode===id?'checked':''} ${isLocked?'disabled':''}><strong>${MODE_LABELS[id]}</strong><span>${MODE_DESCRIPTIONS[id]}</span></label>`).join('')}</div><div class="settings-grid" style="margin-top:14px"><div><label for="round-count">Runden automatisch</label><input id="round-count" type="text" value="Automatisch" disabled></div><div><label for="court-count">Plätze</label><input id="court-count" type="number" min="1" max="12" value="${state.courts}" ${isLocked?'disabled':''}></div></div><div class="settings-grid" style="margin-top:12px"><div><label for="minutes">Minuten je Runde</label><input id="minutes" type="number" min="5" max="60" value="${state.minutes}"></div><div><label for="break-minutes">Pausenzeit</label><input id="break-minutes" type="number" min="0" max="60" value="${state.breakMinutes}"></div></div><div style="margin-top:14px"><label for="final-stage">Turnierabschluss</label><select id="final-stage" ${isLocked?'disabled':''}><option value="table" ${state.finalStage==='table'?'selected':''}>${finalLabel}</option><option value="placement" ${state.finalStage==='placement'?'selected':''}>${finalPlay}</option></select><div class="mode-note">${state.finalStage==='placement'?(state.mode==='roundrobin'?'Nach der Hauptrunde spielen Platz 1 gegen 2, 3 gegen 4 usw.':'Die vier Bestgesetzten spielen Halbfinale, Finale und Platz 3.'):(grouped?'Die jeweiligen Gruppentabellen bilden die Wertung.':'Die Gesamttabelle nach dem letzten Spiel ist das Endergebnis.')}</div></div></section><section class="panel summary"><div class="small muted">Mit der aktuellen Konfiguration</div><div class="summary-grid"><div class="summary-item"><strong>${possible}</strong><span class="small">Plätze gleichzeitig</span></div><div class="summary-item"><strong>Auto</strong><span class="small">Runden</span></div><div class="summary-item"><strong>${s.duration}</strong><span class="small">Minuten circa</span></div></div><button class="gold" id="generate" style="width:100%" ${isLocked?'disabled':''}>Spielplan erstellen</button></section></div>${renderParticipantSetup(isLocked)}</div><div class="footer-note"><span>Bestehende Sicherungen werden automatisch übernommen.</span><span>${grouped?'Gruppenspiele werden automatisch auf die verfügbaren Plätze verteilt.':'Alle Personen werden in einer gemeinsamen Teilnehmerliste geführt.'}</span></div>`}
function bindSetupModern(){$$('[data-player]').forEach(i=>i.oninput=()=>{player(i.dataset.player).name=i.value;invalidate();persist()});$$('[data-group-name]').forEach(i=>i.oninput=()=>{group(i.dataset.groupName).name=i.value||`Gruppe ${i.dataset.groupName}`;persist()});$$('[data-add]').forEach(b=>b.onclick=()=>addPlayer(b.dataset.add));$$('[data-remove]').forEach(b=>b.onclick=()=>removePlayer(b.dataset.remove));$$('[data-remove-group]').forEach(b=>b.onclick=()=>removeGroup(b.dataset.removeGroup));const addGroupButton=$('#add-group'),addPlayerButton=$('#add-player');if(addGroupButton)addGroupButton.onclick=addGroup;if(addPlayerButton)addPlayerButton.onclick=()=>addPlayer();$('#title').oninput=e=>{state.title=e.target.value;persist()};$$('[name=mode]').forEach(i=>i.onchange=()=>{state.mode=i.value;invalidate();persist();render()});$('#final-stage').onchange=e=>{state.finalStage=e.target.value;invalidate();persist();render()};$('#court-count').onchange=e=>{state.courts=Math.max(1,Math.min(12,Number(e.target.value)||1));invalidate();persist();render()};$('#minutes').onchange=e=>{state.minutes=Math.max(5,Math.min(60,Number(e.target.value)||15));resetTimer('Spielzeit');render()};$('#break-minutes').onchange=e=>{state.breakMinutes=Math.max(0,Math.min(60,Number(e.target.value)||0));if(state.timer.mode==='Pause')resetTimer('Pause');else persist();render()};$('#draw-players').onclick=drawPlayers;$('#print-players').onclick=()=>printExtras('players');$('#print-lots').onclick=()=>printExtras('lots');$('#generate').onclick=generate}

const MODE_DESCRIPTIONS_V3={classic:'Die Doppel werden in jeder Runde neu zusammengestellt. Ein Spielerpaar besteht aus je einem Spieler der Gruppe A und einem Spieler der Gruppe B.',mixedfixed:'Die Doppel werden anfangs einmal ausgelost und bleiben über das gesamte Turnier zusammen.',fixedgroups:'Die festen Doppel werden innerhalb ihrer jeweiligen Gruppe gebildet und spielen dort jeder gegen jeden.',roundrobin:'Feste Doppel spielen ohne Gruppen vollständig jeder gegen jeden.',singlesgroups:'Innerhalb jeder Gruppe spielt jede Person im Einzel gegen alle anderen.',singles:'Alle Personen spielen im Einzel ohne Gruppen jeder gegen jeden.'};
function renderParticipantsV3(isLocked){if(!usesGroups(state.mode))return `<div><div class="group-toolbar participant-toolbar"><div><h3>Teilnehmerliste</h3><p class="small muted" style="margin-top:5px">Keine Gruppen: Alle Personen stehen in einer gemeinsamen Liste.</p></div><button class="ghost" id="add-player" ${isLocked?'disabled':''}>+ Person hinzufügen</button></div><section class="panel participant-list-panel"><div class="participant-list">${state.players.map((p,i)=>playerInputRow(p,i,isLocked,true)).join('')}</div></section></div>`;const fixedAB=state.mode==='mixedfixed',note=state.mode==='classic'?'Jedes wechselnde Doppel besteht aus einem Spieler der Gruppe A und einem Spieler der Gruppe B.':fixedAB?'Die Doppel werden einmal aus Gruppe A und Gruppe B gelost und bleiben anschließend zusammen. Weitere Gruppen sind nicht möglich.':state.mode==='fixedgroups'?'Die festen Doppel werden innerhalb ihrer jeweiligen Gruppe gebildet.':'In jeder Gruppe spielt jede Person gegen alle anderen.';return `<div><div class="group-toolbar"><div><h3>Teilnehmergruppen</h3><p class="small muted" style="margin-top:5px">${note}</p></div>${fixedAB?'':`<button class="ghost" id="add-group" ${isLocked?'disabled':''}>+ Gruppe hinzufügen</button>`}</div><div class="player-columns">${state.groups.map(g=>`<section class="panel group-panel"><div class="category-head"><div><input class="group-title" data-group-name="${g.id}" maxlength="30" value="${esc(g.name)}" aria-label="Name Gruppe ${g.id}" ${isLocked?'disabled':''}><div class="color-legend">${players(g.id).length} Personen · Kennung ${g.id}</div></div><div class="group-actions"><button class="ghost" data-add="${g.id}" ${isLocked?'disabled':''}>+ Person</button>${fixedAB?'':`<button class="danger remove-group-button" data-remove-group="${g.id}" ${isLocked||state.groups.length<=1?'disabled':''}>Gruppe entfernen</button>`}</div></div><div class="player-list">${players(g.id).map((p,i)=>playerInputRow(p,i,isLocked)).join('')}</div></section>`).join('')}</div></div>`}
function selectOptions(pool,value){return `<option value="">Person auswählen</option>${pool.map(id=>`<option value="${id}" ${value===id?'selected':''}>${esc(displayName(id))} · ${id}</option>`).join('')}`}
function renderClassicManual(isLocked){syncManualMatches();const all=state.players.map(p=>p.id),defs=manualClassicDefinitions();return `<div class="manual-team-list">${defs.map((d,i)=>`<div class="manual-team-row manual-match-row"><strong>Runde ${d.round} · Platz ${d.court}</strong><div class="manual-match-teams"><div><span class="manual-team-caption">Doppel 1</span><div class="manual-team-selects"><select data-manual-match="${d.key}" data-position="0" ${isLocked?'disabled':''}>${selectOptions(all,state.manualMatches[i].players[0])}</select><span>+</span><select data-manual-match="${d.key}" data-position="1" ${isLocked?'disabled':''}>${selectOptions(all,state.manualMatches[i].players[1])}</select></div></div><b>gegen</b><div><span class="manual-team-caption">Doppel 2</span><div class="manual-team-selects"><select data-manual-match="${d.key}" data-position="2" ${isLocked?'disabled':''}>${selectOptions(all,state.manualMatches[i].players[2])}</select><span>+</span><select data-manual-match="${d.key}" data-position="3" ${isLocked?'disabled':''}>${selectOptions(all,state.manualMatches[i].players[3])}</select></div></div></div></div>`).join('')}</div>`}
function manualLotPairs(){if(state.mode==='classic')return[];if(state.mode==='mixedfixed')return players('A').map((p,i)=>({label:`Doppel ${i+1}`,ids:[p.id,players('B')[i]?.id].filter(Boolean)}));if(state.mode==='fixedgroups')return state.groups.flatMap(g=>{const list=players(g.id);return Array.from({length:Math.floor(list.length/2)},(_,i)=>({label:`${g.name} · Doppel ${i+1}`,ids:[list[i*2].id,list[i*2+1].id]}))});return Array.from({length:Math.floor(state.players.length/2)},(_,i)=>({label:`Doppel ${i+1}`,ids:[state.players[i*2].id,state.players[i*2+1].id]}))}
function digitalDrawPairs(){try{if(state.mode==='classic'){const first=generateClassic()[0];return first?first.matches.flatMap((match,court)=>match.teams.map((ids,side)=>({label:`Platz ${court+1} · Doppel ${side+1}`,ids}))):[]}const teams=state.mode==='mixedfixed'?buildMixedTeams():state.mode==='fixedgroups'?buildFixedTeamsByGroup():buildFixedTeams();return teams.map((ids,i)=>({label:state.mode==='fixedgroups'?`${groupName(player(ids[0])?.group)} · Doppel ${i+1}`:`Doppel ${i+1}`,ids}))}catch{return[]}}
function pairPreviewMarkup(pairs){return pairs.length?`<div class="manual-pair-preview">${pairs.map(pair=>`<div><strong>${esc(pair.label)}</strong><span>${pair.ids.map(id=>esc(displayName(id))).join(' + ')}</span></div>`).join('')}</div>`:'<p class="small muted">Mit der aktuellen Teilnehmerzahl kann noch kein Doppel ausgelost werden.</p>'}
function renderPairingV3(isLocked){if(!supportsPairing(state.mode))return '';if(state.pairing!=='manual')return `<section class="panel pairing-panel"><div class="pairing-head"><div><div class="eyebrow">Auslosung</div><h3>Digital auslosen</h3></div><div class="pairing-choice"><label><input type="radio" name="pairing" value="digital" checked ${isLocked?'disabled':''}> Digital</label><label><input type="radio" name="pairing" value="manual" ${isLocked?'disabled':''}> Mit Loskarten</label></div></div><p class="small muted">${state.mode==='classic'?'Die Doppel werden beim Erstellen für jede Runde automatisch und möglichst abwechslungsreich zusammengestellt.':'Die festen Doppel werden beim Erstellen automatisch und passend zum gewählten Modus ausgelost.'}</p></section>`;const pairs=manualLotPairs();return `<section class="panel pairing-panel"><div class="pairing-head"><div><div class="eyebrow">Auslosung</div><h3>Manuell mit Loskarten</h3></div><div class="pairing-choice"><label><input type="radio" name="pairing" value="digital" ${isLocked?'disabled':''}> Digital</label><label><input type="radio" name="pairing" value="manual" checked ${isLocked?'disabled':''}> Mit Loskarten</label></div></div><div class="manual-lot-workflow"><ol><li>Loskarten über den Button oben ausdrucken und ausschneiden.</li><li>Karten passend zu den Kategorien auslosen.</li><li>Gezogene Namen direkt bei der jeweiligen Kennung in der Teilnehmerliste eintragen.</li><li>Danach den Spielplan erstellen – zusätzliche Auswahlfelder sind nicht nötig.</li></ol></div>${pairs.length?`<div class="manual-preview-refresh"><p>Nach der Eingabe oder Änderung von Namen kannst du hier die Ansicht „Doppel 1“ bis „Doppel ${pairs.length}“ aktualisieren.</p><button class="ghost" type="button" onclick="persist();render();toast('Doppelansicht aktualisiert.')">Doppelansicht aktualisieren</button></div><div class="manual-pair-preview">${pairs.map(p=>`<div><strong>${esc(p.label)}</strong><span>${p.ids.map(id=>esc(displayName(id))).join(' + ')}</span></div>`).join('')}</div>`:'<p class="small muted" style="margin-top:14px">Beim Schleiferlturnier bestimmen die Kennungen den wechselnden Rundenplan. Jedes Doppel besteht aus Gruppe A und Gruppe B.</p>'}</section>`}
function renderSetupV3(){const s=scheduleStats(),possible=state.mode==='classic'?maxClassicCourts():isSinglesMode(state.mode)?Math.min(state.courts,Math.floor(state.players.length/2)):Math.min(state.courts,Math.floor(state.players.length/4)),isLocked=locked(),grouped=usesGroups(state.mode),roundCount=state.schedule.length||effectiveRoundEstimate(),hasFinals=state.mode!=='classic',groupTables=['fixedgroups','singlesgroups'].includes(state.mode),finalLabel=groupTables?'Nach Gruppentabellen auswerten':'Nach Tabelle auswerten',finalPlay=isSinglesMode(state.mode)||state.mode==='fixedgroups'?'Halbfinale und Finale spielen':'Platzierungsspiele durchführen',roundField=state.mode==='classic'?`<div><label for="round-count">Anzahl Runden</label><input id="round-count" type="number" min="1" max="40" value="${state.rounds}" ${isLocked?'disabled':''}></div>`:'';return `<div class="intro"><div><div class="eyebrow">Turnier vorbereiten</div><h2>Modus und Teilnehmer</h2></div><span class="muted">${grouped?`${state.groups.length} Gruppen · `:''}${state.players.length} Personen</span></div>${isLocked?'<div class="notice">Planung gesperrt: Es wurde bereits ein Ergebnis gespeichert. Änderungen sind erst nach „Neues Turnier“ möglich.</div>':''}<div class="draw-toolbar"><button class="primary" id="draw-players" ${isLocked?'disabled':''}>Namen digital auslosen</button><button class="ghost" id="print-players">Spielerliste drucken</button><button class="ghost" id="print-lots">Loskarten drucken</button></div><div class="setup-grid"><div class="settings"><section class="panel"><h3>Rahmen</h3><div style="margin-top:16px"><label for="title">Turniername</label><input id="title" maxlength="80" value="${esc(state.title)}" ${isLocked?'disabled':''}></div><label style="margin-top:14px">Spielmodus</label><div class="mode-grid">${MODE_OPTIONS.map(id=>`<label class="mode-card"><input type="radio" name="mode" value="${id}" ${state.mode===id?'checked':''} ${isLocked?'disabled':''}><strong>${MODE_LABELS[id]}</strong><span>${MODE_DESCRIPTIONS_V3[id]}</span></label>`).join('')}</div><div class="settings-grid dynamic-settings" style="margin-top:14px">${roundField}<div><label for="court-count">Plätze</label><input id="court-count" type="number" min="1" max="12" value="${state.courts}" ${isLocked?'disabled':''}></div></div><div class="settings-grid" style="margin-top:12px"><div><label for="minutes">Minuten je Runde</label><input id="minutes" type="number" min="5" max="60" value="${state.minutes}"></div><div><label for="break-minutes">Pausenzeit</label><input id="break-minutes" type="number" min="0" max="60" value="${state.breakMinutes}"></div></div><div style="margin-top:14px"><label for="final-stage">Turnierabschluss</label>${hasFinals?`<select id="final-stage" ${isLocked?'disabled':''}><option value="table" ${state.finalStage==='table'?'selected':''}>${finalLabel}</option><option value="placement" ${state.finalStage==='placement'?'selected':''}>${finalPlay}</option></select><div class="mode-note">${state.finalStage==='placement'?(['roundrobin','mixedfixed'].includes(state.mode)?'Nach der Hauptrunde spielen Platz 1 gegen 2, 3 gegen 4 usw.':'Die vier Bestgesetzten spielen Halbfinale, Finale und Platz 3.'):(groupTables?'Die jeweiligen Gruppentabellen bilden die Wertung.':'Die Gesamttabelle nach dem letzten Spiel ist das Endergebnis.')}</div>`:'<select id="final-stage" disabled><option>Einzelwertung nach den gespielten Runden</option></select><div class="mode-note">Im Schleiferlturnier wechseln die Doppel jede Runde; gewertet werden deshalb die einzelnen Personen.</div>'}</div></section><section class="panel summary"><div class="small muted">Mit der aktuellen Konfiguration</div><div class="summary-grid"><div class="summary-item"><strong>${possible}</strong><span class="small">Plätze gleichzeitig</span></div><div class="summary-item"><strong>${roundCount}</strong><span class="small">Runden</span></div><div class="summary-item"><strong>${s.duration}</strong><span class="small">Minuten circa</span></div></div><button class="gold" id="generate" style="width:100%" ${isLocked?'disabled':''}>Spielplan erstellen</button></section></div><div class="setup-content">${renderPairingV3(isLocked)}${renderParticipantsV3(isLocked)}</div></div><div class="footer-note"><span>Bestehende Sicherungen werden automatisch übernommen.</span><span>${state.mode==='classic'?'Partner und Gegner wechseln möglichst gleichmäßig.':grouped?'Gruppen- und Finalrunden werden automatisch verteilt.':'Alle Personen werden in einer gemeinsamen Teilnehmerliste geführt.'}</span></div>`}
function changeModeV3(next){if(next==='mixedfixed'&&(state.groups.length!==2||!group('A')||!group('B'))){toast('Für diesen Modus bitte zuerst genau Gruppe A und Gruppe B herstellen.');render();return}state.mode=next;state.pairing='digital';if(next==='classic')state.finalStage='table';invalidate(true);persist();render()}
function bindSetupV3(){$$('[data-player]').forEach(i=>i.oninput=()=>{player(i.dataset.player).name=i.value;invalidate();persist()});$$('[data-group-name]').forEach(i=>i.oninput=()=>{group(i.dataset.groupName).name=i.value||`Gruppe ${i.dataset.groupName}`;persist()});$$('[data-add]').forEach(b=>b.onclick=()=>addPlayer(b.dataset.add));$$('[data-remove]').forEach(b=>b.onclick=()=>removePlayer(b.dataset.remove));$$('[data-remove-group]').forEach(b=>b.onclick=()=>removeGroup(b.dataset.removeGroup));const addGroupButton=$('#add-group'),addPlayerButton=$('#add-player');if(addGroupButton)addGroupButton.onclick=addGroup;if(addPlayerButton)addPlayerButton.onclick=()=>addPlayer();$('#title').oninput=e=>{state.title=e.target.value;persist()};$$('[name=mode]').forEach(i=>i.onchange=()=>changeModeV3(i.value));$$('[name=pairing]').forEach(i=>i.onchange=()=>{state.pairing=i.value;if(i.value==='manual'){if(state.mode==='classic')syncManualMatches();else syncManualTeams()}invalidate(false);persist();render()});$$('[data-manual-team]').forEach(i=>i.onchange=()=>{const entry=state.manualTeams.find(t=>t.key===i.dataset.manualTeam);entry.members[Number(i.dataset.side)]=i.value;invalidate(false);persist()});$$('[data-manual-match]').forEach(i=>i.onchange=()=>{const entry=state.manualMatches.find(m=>m.key===i.dataset.manualMatch);entry.players[Number(i.dataset.position)]=i.value;invalidate(false);persist()});const final=$('#final-stage');if(final&&!final.disabled)final.onchange=e=>{state.finalStage=e.target.value;invalidate();persist();render()};const round=$('#round-count');if(round)round.onchange=e=>{state.rounds=Math.max(1,Math.min(40,Number(e.target.value)||1));invalidate();persist();render()};$('#court-count').onchange=e=>{state.courts=Math.max(1,Math.min(12,Number(e.target.value)||1));invalidate();persist();render()};$('#minutes').onchange=e=>{state.minutes=Math.max(5,Math.min(60,Number(e.target.value)||15));resetTimer('Spielzeit');render()};$('#break-minutes').onchange=e=>{state.breakMinutes=Math.max(0,Math.min(60,Number(e.target.value)||0));if(state.timer.mode==='Pause')resetTimer('Pause');else persist();render()};$('#draw-players').onclick=drawPlayers;$('#print-players').onclick=()=>printExtras('players');$('#print-lots').onclick=()=>printExtras('lots');$('#generate').onclick=generate}

function renderSchedule(){if(!state.schedule.length)return empty('Noch kein Spielplan','Wähle unter „Planung“ den Modus, trage die Personen ein und erstelle anschließend den Spielplan.','Zur Planung','setup');const s=scheduleStats(),footer=state.mode==='classic'?'Die Doppel werden in jeder Runde neu zusammengestellt.':state.mode==='mixedfixed'?'Jedes feste Doppel besteht aus Gruppe A + Gruppe B.':['fixedgroups','singlesgroups'].includes(state.mode)?'Zuerst die Gruppenphase, danach optional die Finalrunde.':isSinglesMode(state.mode)?'Alle Personen spielen im Einzel jeder gegen jeden.':'Die ausgelosten Doppel bleiben über das Turnier zusammen.';return `<div class="intro"><div><div class="eyebrow">${esc(state.title)} · ${MODE_LABELS[state.mode]}</div><h2>Alle Runden im Überblick</h2></div><button class="ghost no-print" id="print-schedule">Gesamten Spielplan drucken</button></div><section class="timer-panel no-print" aria-label="Turnieruhr"><div class="timer-copy"><span class="timer-icon" aria-hidden="true">⏱</span><div><strong id="timer-mode">${state.timer.mode}</strong><div class="small muted" id="timer-status">Bereit</div></div></div><div class="timer-digits" id="timer-digits">${Math.floor(remaining()/60).toString().padStart(2,'0')}:${(remaining()%60).toString().padStart(2,'0')}</div><div class="timer-actions"><button class="light" id="timer-toggle">Start</button><button class="ghost" id="timer-reset">Zurücksetzen</button><button class="gold" id="timer-break">Pause starten</button></div></section><div class="schedule-overview"><div class="rounds no-print">${state.schedule.map((x,i)=>`<button data-round="${i}" class="${i===state.currentRound?'active ':''}${roundComplete(i)?'completed ':''}${!roundUnlocked(i)?'locked':''}" ${!roundUnlocked(i)?'disabled':''}>${x.round}</button>`).join('')}</div><div class="schedule-facts"><span>${state.schedule.length} Runden</span><span>${s.games} Begegnungen</span><span>${state.minutes} + ${state.breakMinutes} Min.</span></div></div><div class="schedule-list">${state.schedule.map((r,i)=>renderRound(r,i)).join('')}</div><div class="footer-note"><span>${state.minutes} Minuten Spielzeit · ${state.breakMinutes} Minuten Pause</span><span>${footer}</span></div>`}
function renderRound(r,index){const entered=roundResultCount(index),total=r.matches.length,isLocked=!roundUnlocked(index),percent=total?entered/total*100:100,isFinal=['placement','semifinal','final'].includes(r.type),label=r.type==='placement'?'Platzierung':r.type==='semifinal'?'Halbfinale':r.type==='final'?'Finalrunde':r.type==='group'?`Gruppenphase · Runde ${r.round}`:`Runde ${r.round}`,byes=roundByes(r);return `<section class="round-block ${isFinal?'placement ':''}${index===state.currentRound?'current ':''}${isLocked?'locked':''}" id="round-${r.round}" data-round-section="${index}"><div class="round-heading"><div class="round-title"><span class="round-number">${r.round}</span><div><h3>${label}</h3><div class="small muted">${r.matches.length} ${r.matches.length===1?'Platz':'Plätze'} belegt</div></div></div><div class="round-meta"><span class="phase-badge">${isFinal?'Finalphase':r.type==='group'?'Gruppenphase':'Hauptrunde'}</span><span>${state.minutes} Min. Spielzeit</span></div></div><div class="round-progress"><div class="round-progress-copy"><span class="small muted">${entered} von ${total} Ergebnissen in dieser Runde eingetragen.</span><strong>${entered===total?'Runde vollständig':isLocked?'Noch gesperrt':'Eingabe möglich'}</strong></div><div class="round-progress-track"><div class="round-progress-fill" style="width:${percent}%"></div></div></div>${isLocked?`<div class="round-lock">Bitte zuerst Runde ${r.round-1} vollständig abschließen.</div>`:''}<div class="matches">${r.matches.map(m=>renderMatch(m,isLocked)).join('')}</div><div class="bye-panel"><h3>Pause in dieser Runde</h3><div class="bye-list">${byes.length?byes.map(id=>`<span class="bye" style="--player-color:${playerColor(id)}"><span class="player-dot"></span>${esc(displayName(id))}${usesGroups(state.mode)?` · ${esc(groupName(player(id)?.group))}`:''}</span>`).join(''):'<span class="bye">Niemand – alle spielen</span>'}</div></div></section>`}
function renderTeam(ids,placeholder=''){if(!ids?.length)return `<div class="team"><div class="player-name">${esc(placeholder)}</div><div class="level">Wird nach der Hauptrunde bestimmt</div></div>`;return `<div class="team">${ids.map(id=>`<div style="margin-bottom:10px;--player-color:${playerColor(id)}"><div class="player-label"><span class="player-dot"></span><span class="player-name">${esc(displayName(id))}</span></div>${usesGroups(state.mode)?`<div class="level">${esc(groupName(player(id)?.group))}</div>`:''}</div>`).join('')}</div>`}
function renderMatch(m,isLocked=false){const result=state.results[m.id],teams=resolvedTeams(m),unresolved=teams.some(t=>!t.length),disabled=isLocked||unresolved?' disabled':'',placeholder=m.placement?m.placement.map(n=>`Platz ${n}`):m.seed?m.seed.map(n=>`Setzplatz ${n}`):m.sources?['Sieger/Verlierer Halbfinale','Sieger/Verlierer Halbfinale']:['',''],badge=m.label||(m.placement?`Platz ${m.placement[0]} gegen ${m.placement[1]}`:m.seed?`Setzplatz ${m.seed[0]} gegen ${m.seed[1]}`:result?'Ergebnis gespeichert':isSinglesMode(state.mode)?'Einzel':state.mode==='classic'?'Doppel':'Festes Doppel');return `<article class="match ${result?'saved':''}" data-match="${m.id}"><div class="match-top"><span class="court">PLATZ ${m.court}</span><span class="pill">${badge}</span></div><div class="team-vs">${renderTeam(teams[0],placeholder[0])}<span class="vs">VS</span>${renderTeam(teams[1],placeholder[1])}</div><div class="score"><input data-score="${m.id}" data-side="0" type="number" min="0" max="99" step="1" inputmode="numeric" aria-label="Spielstand Seite 1" value="${result?.[0]??''}" placeholder="–"${disabled}><span>:</span><input data-score="${m.id}" data-side="1" type="number" min="0" max="99" step="1" inputmode="numeric" aria-label="Spielstand Seite 2" value="${result?.[1]??''}" placeholder="–"${disabled}></div><button class="save-result ${result?'ghost':'primary'}" data-save="${m.id}" data-mode="${result?'edit':'save'}"${disabled}>${result?'✓ Ergebnis ändern':isLocked?'Runde gesperrt':unresolved?'Paarung noch offen':'Ergebnis speichern'}</button></article>`}
function enterResultEdit(card){card.classList.remove('saved');const b=card.querySelector('[data-save]');b.dataset.mode='save';b.textContent='Ergebnis speichern';b.classList.remove('ghost');b.classList.add('primary')}
function bindSchedule(){$$('[data-round]').forEach(b=>b.onclick=()=>{const next=Number(b.dataset.round);if(!roundUnlocked(next)){toast(`Bitte zuerst Runde ${next} vollständig abschließen.`);return}state.currentRound=next;state.timer={remaining:state.minutes*60,end:null,mode:'Spielzeit'};releaseWake();persist();render();requestAnimationFrame(()=>$(`#round-${next+1}`)?.scrollIntoView({behavior:'smooth',block:'start'}))});$$('[data-score]').forEach(input=>input.oninput=()=>{const card=input.closest('.match');if(card.querySelector('[data-save]').dataset.mode==='edit')enterResultEdit(card)});$$('[data-save]').forEach(b=>b.onclick=()=>{const card=b.closest('.match'),id=b.dataset.save,index=state.schedule.findIndex(r=>r.matches.some(m=>m.id===id));if(!roundUnlocked(index))return;if(b.dataset.mode==='edit'){enterResultEdit(card);card.querySelector('input')?.focus();return}const values=[...card.querySelectorAll('input')].map(i=>i.value);if(values.some(v=>v==='')){toast('Bitte beide Spielstände eintragen.');return}const nums=values.map(Number);if(nums.some(n=>!Number.isInteger(n)||n<0||n>99)){toast('Erlaubt sind ganze Spielstände von 0 bis 99.');return}if(['placement','semifinal','final'].includes(state.schedule[index]?.type)&&nums[0]===nums[1]){toast('In Final- und Platzierungsspielen muss ein Sieger feststehen.');return}state.results[id]=nums;persist();render();toast(roundComplete(index)?index<state.schedule.length-1?'Runde vollständig. Die nächste Runde ist freigeschaltet.':'Turnier vollständig.':'Ergebnis gespeichert.')});$('#timer-toggle').onclick=toggleTimer;$('#timer-reset').onclick=()=>resetTimer(state.timer.mode);$('#timer-break').onclick=()=>{if(!state.breakMinutes){toast('Die Pausenzeit ist auf 0 Minuten eingestellt.');return}state.timer={remaining:state.breakMinutes*60,end:Date.now()+state.breakMinutes*60000,mode:'Pause'};persist();requestWake();updateTimer()};$('#print-schedule').onclick=()=>printExtras('schedule');updateTimer()}

function standingsPerson(id){return `<div class="standings-player" style="--player-color:${playerColor(id)}"><span class="player-dot"></span><div><strong>${esc(displayName(id))}</strong><div class="small muted">${esc(id)}</div></div></div>`}
function standingsTable(rows,teamMode=false,showGroup=usesGroups(state.mode)){const personLabel=teamMode?'Doppel':'Spieler';return `<div class="table-wrap"><table class="standings-table"><thead><tr><th>Platz</th><th>${personLabel}</th>${showGroup?'<th>Gruppe</th>':''}<th>Spiele</th><th>Siege</th><th>Unentschieden</th><th>Punkte</th><th>Spieldifferenz</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="rank" data-label="Platz">${r.rank||'–'}</td><td data-label="${personLabel}">${teamMode?`<div class="standings-team">${r.members.map(standingsPerson).join('')}</div>`:standingsPerson(r.id)}</td>${showGroup?`<td data-label="Gruppe">${esc(groupName(r.group))}</td>`:''}<td data-label="Spiele">${r.played}</td><td data-label="Siege">${r.wins}</td><td data-label="Unentschieden">${r.draws}</td><td class="points" data-label="Punkte">${r.points}</td><td data-label="Spieldifferenz">${r.diff>0?'+':''}${r.diff}</td></tr>`).join('')}</tbody></table></div>`}
function renderStandings(){if(!state.schedule.length)return empty('Noch keine Tabelle','Die Wertung erscheint, sobald ein Spielplan erstellt wurde.','Spielplan erstellen','setup');const data=standings(),teamMode=data.kind==='team',groupTables=data.groups?`<div class="player-columns standings-groups">${data.groups.map(g=>`<section class="panel"><h3 style="margin-bottom:14px">${esc(g.name)}</h3>${standingsTable(g.rows,teamMode,false)}</section>`).join('')}</div><section class="panel" style="margin-top:20px"><h3 style="margin-bottom:14px">${state.finalStage==='placement'?'Finalwertung':'Gesamtübersicht nach Gruppensetzung'}</h3>${standingsTable(data.rows,teamMode,true)}</section>`:`<section class="panel">${standingsTable(data.rows,teamMode,false)}</section>`;return `<div class="intro"><div><div class="eyebrow">${MODE_LABELS[state.mode]} · ${state.finalStage==='placement'?'mit Finalspielen':'Tabellenwertung'}</div><h2>${data.groups?'Gruppentabellen & Gesamtwertung':teamMode?'Doppel-Tabelle':'Einzel-Tabelle'}</h2></div><button class="ghost no-print" onclick="window.print()">Tabelle drucken</button></div>${groupTables}<p class="small muted" style="margin-top:14px">Sieg 2 Punkte, Unentschieden 1 Punkt. Danach entscheiden Spieldifferenz und gewonnene Spiele.${state.finalStage==='placement'&&state.mode!=='roundrobin'?' Die vier Bestgesetzten erreichen die Finalrunde.':state.finalStage==='placement'?' Die endgültigen Plätze werden durch die Platzierungsspiele festgelegt.':''}</p>`}
function renderRules(){const s=scheduleStats(),groupText=usesGroups(state.mode)?` · ${state.groups.length} Gruppen`:'';return `<div class="intro"><div><div class="eyebrow">Klarer Ablauf</div><h2>Spielmodi & Regeln</h2></div><button class="ghost no-print" id="print-places">Platzkarten erstellen</button></div><div class="rules-grid"><section class="panel"><h3>Schleiferlturnier</h3><p>Die Doppel werden in jeder Runde neu zusammengestellt. Ein Spielerpaar besteht aus je einem Spieler der Gruppe A und einem Spieler der Gruppe B.</p></section><section class="panel"><h3>Geloste Doppel aus zwei Kategorien</h3><p>Die Doppel werden anfangs einmal ausgelost und bleiben über das gesamte Turnier zusammen. Jedes Doppel besteht aus Gruppe A und Gruppe B; zusätzliche Gruppen sind ausgeschlossen.</p></section><section class="panel"><h3>Feste Doppel mit Gruppen</h3><p>Die Doppel werden innerhalb jeder Gruppe einmal ausgelost und spielen anschließend jedes gegen jedes.</p></section><section class="panel"><h3>Round Robin</h3><p>Feste Doppel werden ohne Gruppen einmal ausgelost und spielen vollständig jedes gegen jedes.</p></section><section class="panel"><h3>Einzel mit Gruppen</h3><p>Innerhalb jeder Gruppe spielt jede Person einmal gegen jede andere. Optional folgen Halbfinale, Finale und Spiel um Platz 3.</p></section><section class="panel"><h3>Einzel ohne Gruppen</h3><p>Alle Personen werden in einer gemeinsamen Liste geführt und spielen jeweils einmal gegeneinander.</p></section><section class="panel"><h3>Digital oder mit Loskarten</h3><p>Digital werden die Namen automatisch ausgelost. Bei der manuellen Variante werden Loskarten gedruckt und gezogen; anschließend werden die Namen direkt bei den jeweiligen Kennungen in der Teilnehmerliste eingetragen. Dropdown-Auswahlfelder sind nicht erforderlich.</p></section><section class="panel"><h3>Platzierungs- und Finalspiele</h3><p>Die Paarungen werden erst nach vollständig eingetragenen Ergebnissen der Haupt- beziehungsweise Gruppenphase aufgelöst. In diesen Spielen muss ein Sieger feststehen.</p></section><section class="panel"><h3>Tenniszählweise & Zeitende</h3><p>Es wird regulär mit 0, 15, 30 und 40 gezählt. Beim Zeitsignal gilt der Stand der vollständig beendeten Spiele; ein laufendes Spiel wird nicht gewertet.</p></section><section class="panel"><h3>Aktueller Rahmen</h3><p><strong>${state.players.length} Personen</strong>${groupText} · ${MODE_LABELS[state.mode]}</p><p><strong>${state.schedule.length||effectiveRoundEstimate()} Runden</strong> · bis zu ${s.active} Plätze · etwa ${s.duration} Minuten.</p></section></div>`}
function bindRules(){$('#print-places').onclick=()=>printExtras('places')}

function printTeam(ids){return ids.map(id=>`<div class="print-player-line"><strong>${esc(displayName(id))}</strong>${usesGroups(state.mode)?`<span> · ${esc(groupName(player(id)?.group))}</span>`:''}</div>`).join('')}
function matchPlaceholder(m,side){return m.placement?`Platz ${m.placement[side]}`:m.seed?`Setzplatz ${m.seed[side]}`:m.sources?'Ergebnis Halbfinale':'Noch nicht bestimmt'}
function roundPrintTitle(r){return r.type==='placement'?'Platzierungsrunde':r.type==='semifinal'?'Halbfinale':r.type==='final'?'Finalrunde':r.type==='group'?`Gruppenphase · Runde ${r.round}`:`Runde ${r.round}`}
function printExtras(kind){let html='';if(kind==='players'){const sets=usesGroups(state.mode)?state.groups.map(g=>({name:g.name,list:players(g.id)})):[{name:'Teilnehmerliste',list:state.players}];for(const set of sets)html+=`<section class="print-sheet"><h1>${esc(state.title)} · ${esc(set.name)}</h1><table class="print-list"><thead><tr><th>Nr.</th><th>Name</th></tr></thead><tbody>${set.list.map((p,i)=>`<tr><td><strong>${usesGroups(state.mode)?p.id:i+1}</strong></td><td>${esc(p.name||'________________________')}</td></tr>`).join('')}</tbody></table></section>`}else if(kind==='lots'){const sets=usesGroups(state.mode)?state.groups.map(g=>({name:g.name,list:players(g.id)})):[{name:'Teilnehmer',list:state.players}];for(const set of sets){for(let page=0;page<set.list.length;page+=6)html+=`<section class="print-sheet"><h1>Loskarten · ${esc(set.name)}</h1><p>Ausdrucken, ausschneiden und mischen.</p><div class="los-grid">${set.list.slice(page,page+6).map((p,i)=>`<div class="los-card" style="--player-color:${playerColor(p.id)}"><span>${esc(set.name).toUpperCase()}</span><div class="lot-code"><span class="lot-color"></span>${usesGroups(state.mode)?p.id:page+i+1}</div><p>Name: ________________________</p></div>`).join('')}</div></section>`}}else if(kind==='schedule'){if(!state.schedule.length)return toast('Bitte zuerst einen Spielplan erstellen.');const s=scheduleStats(),quote=state.mode==='classic'?'Neue Runde - Neuer Partner! Viel Spaß &amp; ein verletzungsfreies Spiel.':isSinglesMode(state.mode)?'Fairer Wettkampf. Viel Spaß &amp; ein verletzungsfreies Spiel.':'Feste Partner - neue Gegner! Viel Spaß &amp; ein verletzungsfreies Spiel.';html=`<section class="print-sheet print-schedule-sheet"><div class="print-kicker">${esc(MODE_LABELS[state.mode])} · Gesamtübersicht</div><h1 class="print-title">${esc(state.title)}</h1><p class="print-quote">${quote}</p><div class="print-summary"><span>${state.schedule.length} Runden</span><span>${s.active} Plätze</span><span>${state.minutes} Min. Spiel · ${state.breakMinutes} Min. Pause</span></div>${state.schedule.map(r=>{const byes=roundByes(r);return `<section class="print-round"><h2>${roundPrintTitle(r)}</h2><table><thead><tr><th>Platz</th><th>${isSinglesMode(state.mode)?'Person 1':'Doppel 1'}</th><th>${isSinglesMode(state.mode)?'Person 2':'Doppel 2'}</th><th>Ergebnis</th></tr></thead><tbody>${r.matches.map(m=>{const score=state.results[m.id],teams=resolvedTeams(m);return `<tr><td><strong>${m.court}</strong></td><td>${teams[0].length?printTeam(teams[0]):esc(matchPlaceholder(m,0))}</td><td>${teams[1].length?printTeam(teams[1]):esc(matchPlaceholder(m,1))}</td><td>${score?`${score[0]} : ${score[1]}`:'–'}</td></tr>`}).join('')}</tbody></table>${byes.length?`<p class="print-byes"><strong>Pause:</strong> ${byes.map(displayName).map(esc).join(', ')}</p>`:''}</section>`}).join('')}<div class="place-card-footer"><span>Viel Freude bei fairen Spielen!</span><span>Erstellt von Andreas Teichert</span></div></section>`}else if(kind==='places'){if(!state.schedule.length)return toast('Bitte zuerst einen Spielplan erstellen.');const max=Math.max(...state.schedule.flatMap(r=>r.matches.map(m=>m.court)));for(let place=1;place<=max;place++)html+=`<section class="print-sheet"><div class="place-card"><div class="place-card-head"><div><div class="print-kicker">${esc(state.title)} · Platzkarte</div><h1 class="print-title">Willkommen auf dem Platz</h1></div><span class="place-badge">${esc(MODE_LABELS[state.mode])}</span></div><div class="place-number">PLATZ ${place}</div><table><thead><tr><th>Runde</th><th>Begegnung</th></tr></thead><tbody>${state.schedule.map(r=>{const m=r.matches.find(x=>x.court===place),teams=m?resolvedTeams(m):null;return `<tr><td><strong>${r.round}</strong></td><td>${m&&teams[0].length?`<div class="print-encounter"><div>${printTeam(teams[0])}</div><span class="print-vs">gegen</span><div>${printTeam(teams[1])}</div></div>`:m?esc(matchPlaceholder(m,0))+' gegen '+esc(matchPlaceholder(m,1)):'Platz frei'}</td></tr>`}).join('')}</tbody></table><div class="place-card-footer"><span>Viel Spaß und faire Spiele!</span><span>Erstellt von Andreas Teichert</span></div></div></section>`}$('#print-extra').innerHTML=html;document.body.classList.add('printing-extra');window.print()}

function empty(title,text,label,target){return `<section class="panel empty"><h2>${title}</h2><p>${text}</p><button class="primary" data-go="${target}">${label}</button></section>`}
function updateBrand(){const planned=state.schedule.length>0;$('#brand-title').textContent=planned?'Schleiferlturnier':'Turniergenerator';$('#brand-subtitle').textContent=planned?'Flexible Turniermodi · Foto Edition':'Plane dein Turnier - einfach & unkompliziert.'}
function setClassicRoundMode(automatic){state.roundMode=automatic?'auto':'manual';invalidate();persist();render()}
function prepareSetupControls(){const draw=$('#draw-players'),lots=$('#print-lots'),pairingPanel=$('.pairing-panel'),toolbar=$('.draw-toolbar');if(toolbar&&toolbar.children.length===1)toolbar.classList.add('single-action');if(state.pairing==='digital'&&pairingPanel&&draw){const area=document.createElement('div');area.className='digital-draw-area';area.innerHTML='<div><strong>Doppel digital auslosen</strong><p>Die Namen werden passend zum gewählten Modus zufällig verteilt.</p></div>';draw.hidden=false;draw.textContent=state.digitalDrawn?'Erneut auslosen':'Jetzt auslosen';draw.className='primary';area.append(draw);pairingPanel.append(area);const preview=document.createElement('div');preview.id='digital-draw-preview';preview.className='digital-draw-preview';preview.innerHTML=state.digitalDrawn?`<div class="preview-heading"><strong>Geloste Doppel</strong><span>${state.mode==='classic'?'Vorschau für Runde 1':'Bleiben für das Turnier zusammen'}</span></div>${pairPreviewMarkup(digitalDrawPairs())}`:'<p class="small muted">Trage zuerst alle Namen ein und starte anschließend die Auslosung.</p>';pairingPanel.append(preview)}else if(draw)draw.hidden=true;if(state.pairing==='manual'&&pairingPanel&&lots){const actions=document.createElement('div');actions.className='manual-lot-actions';lots.textContent='Loskarten drucken';actions.append(lots);const workflow=pairingPanel.querySelector('.manual-lot-workflow');workflow?.after(actions)}else if(lots)lots.hidden=true;if(state.mode!=='classic')return;const input=$('#round-count');if(!input)return;const automatic=state.roundMode==='auto',calculated=classicAutoRounds(),wrap=input.parentElement,label=wrap.querySelector('label');label.textContent='Runden';const row=document.createElement('div');row.className='round-setting-row';const auto=document.createElement('label');auto.className='round-auto-toggle';auto.innerHTML=`<input id="round-auto" type="checkbox" ${automatic?'checked':''} ${locked()?'disabled':''} onchange="setClassicRoundMode(this.checked)"><span>Auto (${calculated} Runden)</span>`;wrap.insertBefore(row,input);row.append(auto,input);input.disabled=automatic||locked();input.setAttribute('aria-label','Eigene Rundenzahl');const hint=document.createElement('div');hint.className='round-setting-hint';hint.textContent=automatic?'Alle möglichen Partnerschaften werden einmal durchlaufen.':'Eigene Rundenzahl eintragen oder Auto aktivieren.';wrap.append(hint)}
function finalizeSetupUsability(){const content=$('.setup-content'),pairing=$('.pairing-panel');if(content&&pairing)content.append(pairing);const participantToolbar=$('.group-toolbar'),printPlayers=$('#print-players');if(participantToolbar&&printPlayers){const actions=document.createElement('div');actions.className='participant-toolbar-actions';const directButton=[...participantToolbar.children].find(child=>child.tagName==='BUTTON');if(directButton)actions.append(directButton);actions.append(printPlayers);participantToolbar.append(actions)}const firstManualStep=$('.manual-lot-workflow li');if(firstManualStep)firstManualStep.textContent='Loskarten hier ausdrucken und anschließend ausschneiden.';const topToolbar=$('.draw-toolbar');if(topToolbar&&!([...topToolbar.children].some(child=>!child.hidden)))topToolbar.hidden=true}
function render(){updateBrand();document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false')});$('#main').innerHTML=({setup:renderSetupV3,schedule:renderSchedule,standings:renderStandings,rules:renderRules}[view])();if(view==='setup'){prepareSetupControls();finalizeSetupUsability()}({setup:bindSetupV3,schedule:bindSchedule,standings:()=>{},rules:bindRules}[view])();const titleInput=$('#title');if(titleInput)titleInput.placeholder='Gib hier den Namen deines Turniers ein.';$$('[data-go]').forEach(b=>b.onclick=()=>{view=b.dataset.go;render()})}

function migrate(raw){if(!raw||typeof raw!=='object')return raw;if(raw.version===2)return raw;const groups=[...new Set((raw.players||[]).map(p=>p.level==='F'?'B':p.level||p.group).filter(Boolean))].map(id=>({id,name:`Gruppe ${id}`}));return{...fresh(),...raw,version:2,mode:'classic',finalStage:'table',groups:groups.length>=2?groups:fresh().groups,players:(raw.players||[]).map(p=>({id:p.id?.[0]==='F'?'B'+p.id.slice(1):p.id,group:p.level==='F'?'B':p.level||p.group,name:p.name||''})),fixedTeams:[]}}
function validate(raw){if(!raw||raw.version!==2||!Array.isArray(raw.groups)||raw.groups.length<1||!Array.isArray(raw.players)||!Array.isArray(raw.schedule)||!raw.results||typeof raw.results!=='object')throw new Error('Das ist keine gültige Schleiferlturnier-Sicherung.');raw.pairing=['digital','manual'].includes(raw.pairing)?raw.pairing:'digital';raw.roundMode=['auto','manual'].includes(raw.roundMode)?raw.roundMode:'manual';raw.manualTeams=Array.isArray(raw.manualTeams)?raw.manualTeams:[];raw.manualMatches=Array.isArray(raw.manualMatches)?raw.manualMatches:[];if(!['fixedgroups','mixedfixed','roundrobin','singlesgroups','singles','classic','fixed'].includes(raw.mode)||!['table','placement'].includes(raw.finalStage))throw new Error('Ungültiger Spielmodus.');if(!raw.groups.every(g=>g&&/^[A-Z]$/.test(g.id)&&typeof g.name==='string'&&g.name.length<=30)||new Set(raw.groups.map(g=>g.id)).size!==raw.groups.length)throw new Error('Ungültige Gruppen.');const groupSet=new Set(raw.groups.map(g=>g.id));if(!raw.players.every(p=>p&&typeof p.id==='string'&&groupSet.has(p.group)&&p.id.startsWith(p.group)&&typeof p.name==='string'&&p.name.length<=60)||new Set(raw.players.map(p=>p.id)).size!==raw.players.length||(usesGroups(raw.mode)&&raw.groups.some(g=>raw.players.filter(p=>p.group===g.id).length<2)))throw new Error('Ungültige Teilnehmerliste.');if(raw.mode==='mixedfixed'&&(raw.groups.length!==2||!groupSet.has('A')||!groupSet.has('B')))throw new Error('Der Modus Gruppe A + Gruppe B benötigt genau diese beiden Gruppen.');if(!Number.isInteger(raw.rounds)||raw.rounds<1||raw.rounds>40||!Number.isInteger(raw.courts)||raw.courts<1||raw.courts>12||!Number.isInteger(raw.minutes)||raw.minutes<5||raw.minutes>60||!Number.isInteger(raw.breakMinutes)||raw.breakMinutes<0||raw.breakMinutes>60)throw new Error('Ungültige Turniereinstellungen.');const known=new Set(raw.players.map(p=>p.id)),ids=new Set(),teamSize=isSinglesMode(raw.mode)?1:2;if(!raw.manualTeams.every(t=>t&&typeof t.key==='string'&&Array.isArray(t.members)&&t.members.length===2&&t.members.every(id=>id===''||known.has(id)))||!raw.manualMatches.every(m=>m&&typeof m.key==='string'&&Array.isArray(m.players)&&m.players.length===4&&m.players.every(id=>id===''||known.has(id))))throw new Error('Ungültige manuelle Paarungen.');for(const r of raw.schedule){if(!r||!Array.isArray(r.matches)||!Array.isArray(r.byes))throw new Error('Ungültiger Spielplan.');for(const m of r.matches){if(!m||typeof m.id!=='string'||ids.has(m.id))throw new Error('Ungültiger Spielplan.');ids.add(m.id);if(m.teams&&(!Array.isArray(m.teams)||m.teams.length!==2||m.teams.some(t=>!Array.isArray(t)||t.length!==teamSize||t.some(id=>!known.has(id)))))throw new Error('Ungültiger Spielplan.')}}for(const [id,score] of Object.entries(raw.results))if(!ids.has(id)||!Array.isArray(score)||score.length!==2||score.some(n=>!Number.isInteger(n)||n<0||n>99))throw new Error('Ungültiges Ergebnis.');raw.fixedTeams=Array.isArray(raw.fixedTeams)?raw.fixedTeams:[];raw.currentRound=Math.max(0,Math.min(Number(raw.currentRound)||0,Math.max(0,raw.schedule.length-1)));return raw}

function publicStandings(){const data=standings(),row=r=>({rank:r.rank,id:r.id,name:r.name,group:usesGroups(state.mode)&&r.group?groupName(r.group):null,members:r.members?.map(id=>({id,name:displayName(id),group:usesGroups(state.mode)?groupName(player(id)?.group):null}))||null,played:r.played,wins:r.wins,draws:r.draws,points:r.points,for:r.for,against:r.against,diff:r.diff});return{kind:data.kind,rows:data.rows.map(row),groups:data.groups?.map(g=>({id:g.id,name:g.name,rows:g.rows.map(row)}))||null}}
function publicSnapshot(){const info=id=>({id,name:displayName(id),group:usesGroups(state.mode)?groupName(player(id)?.group):null,color:playerColor(id)}),s=scheduleStats();return{version:2,type:'schleiferl',exportedAt:new Date().toISOString(),title:state.title,mode:state.mode,modeLabel:MODE_LABELS[state.mode],finalStage:state.finalStage,summary:{players:state.players.length,groups:usesGroups(state.mode)?state.groups.length:0,rounds:state.schedule.length,courts:s.active,results:Object.keys(state.results).length,matches:s.games,minutes:state.minutes,breakMinutes:state.breakMinutes},standings:publicStandings(),rounds:state.schedule.map(r=>({number:r.round,type:r.type,matches:r.matches.map(m=>({id:m.id,court:m.court,label:m.label||(m.placement?`Platz ${m.placement[0]} gegen ${m.placement[1]}`:m.seed?`Setzplatz ${m.seed[0]} gegen ${m.seed[1]}`:null),teams:resolvedTeams(m).map(t=>t.map(info)),score:state.results[m.id]||null})),byes:roundByes(r).map(info)}))}}
function download(name,data){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.href=url;a.download=name;a.hidden=true;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function downloadBackup(){download(`Schleiferlturnier-${new Date().toISOString().slice(0,10)}.json`,state);toast('Sicherung erstellt.')}
function downloadPublicStand(){download('schleiferlturnierstand.json',publicSnapshot());toast('Online-Turnierstand exportiert. Datei im Repository ersetzen.')}
function openBackup(){const d=$('#dialog');d.innerHTML=`<h2>Turnierstand sichern &amp; veröffentlichen</h2><p>Die öffentliche JSON-Datei versorgt beide Nur-Lese-Seiten.</p><div class="dialog-actions"><button class="ghost" id="export">Sicherung herunterladen</button><button class="ghost" id="export-public">Online-Stand exportieren</button><button class="ghost" id="import">Sicherung einlesen</button><button class="danger" id="reset">Neues Turnier</button><button class="primary" id="close">Schließen</button></div><div class="live-links"><a href="schleiferlturnier_live.html" target="_blank" rel="noopener">Live-Spielplan öffnen</a><a href="schleiferlturnier_ergebnisse.html" target="_blank" rel="noopener">Finale Tabelle &amp; Ergebnisse öffnen</a></div>`;d.showModal();$('#close').onclick=()=>d.close();$('#export').onclick=downloadBackup;$('#export-public').onclick=downloadPublicStand;$('#import').onclick=()=>{$('#import-file').click();d.close()};$('#reset').onclick=()=>{if(!confirm('Alle Teilnehmer, Paarungen und Ergebnisse löschen?'))return;state=fresh();view='setup';persist();render();d.close();toast('Neues Turnier angelegt.')}}

$('#import-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>1000000)throw new Error('Die Sicherung ist zu groß.');const imported=validate(migrate(JSON.parse(await file.text())));if(!confirm('Den aktuellen Turnierstand vollständig ersetzen?'))return;state=imported;persist();view='schedule';render();toast('Sicherung eingelesen.')}catch(err){toast(err instanceof SyntaxError?'Die Datei enthält keine gültigen Daten.':err.message)}};
$('#backup').onclick=openBackup;
$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});
try{const saved=localStorage.getItem(KEY)||LEGACY_KEYS.map(key=>localStorage.getItem(key)).find(Boolean);if(saved){state=validate(migrate(JSON.parse(saved)));localStorage.setItem(KEY,JSON.stringify(state))}}catch{state=fresh()}
render();
window.addEventListener('afterprint',()=>{document.body.classList.remove('printing-extra');$('#print-extra').innerHTML=''});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){updateTimer();if(state.timer.end)requestWake()}});
setInterval(updateTimer,250);
